import { createHash } from 'node:crypto';

const statuses = ['planned', 'planted', 'echoed', 'resolved'];
const outcomes = ['open', 'advancing', 'blocked', 'resolved', 'fulfilled', 'abandoned'];

/** Evaluation admission only. Expectations never enter the application/model. */
export function validateNarrativeStoryCorpus(corpus, sourceBytes) {
  if (![1, 2, 3].includes(corpus.version) || corpus.schema !== 'narrative-story-evaluation-corpus-v' + corpus.version) throw Error('Unsupported story corpus');
  if (createHash('sha256').update(sourceBytes).digest('hex') !== corpus.sourceSha256) throw Error('Frozen story source hash mismatch');
  const sourceText = sourceBytes.toString('utf8');
  if (!Array.isArray(corpus.cases) || !corpus.cases.length || new Set(corpus.cases.map(c => c.id)).size !== corpus.cases.length) throw Error('Corpus case identity is invalid');
  for (const item of corpus.cases) if (!item.text || !sourceText.includes(item.text)) throw Error('Case excerpt is not verbatim: ' + item.id);
  if (corpus.version >= 2 && corpus.cases.some(item => item.table !== 'foreshadows' || !Array.isArray(item.initialDevelopments)
    || item.initialDevelopments.length < 2 || new Set(item.initialDevelopments.map(child => child.id)).size !== item.initialDevelopments.length)) throw Error('Target-state corpus must declare multiple distinct prior children');
  if (corpus.version === 3) {
    if (typeof corpus.objectName !== 'string' || !corpus.objectName.trim() || !sourceText.includes(corpus.objectName)) throw Error('Version 3 requires a story-grounded object name');
    for (const item of corpus.cases) {
      if (!statuses.includes(item.initialBusinessStatus)) throw Error('Declare a valid business status before model dispatch');
      const expected = item.expected?.developments;
      if (!expected || Object.keys(expected).length !== item.initialDevelopments.length) throw Error('Every prior child requires a separately frozen expectation');
      for (const child of item.initialDevelopments) {
        const target = expected[child.id];
        if (!target || !Array.isArray(target.states) || !target.states.length || target.states.some(state => !outcomes.includes(state))
          || !['intent', 'established'].includes(target.modality)) throw Error('Invalid development expectation');
        if (child.modality !== 'intent' || !['open', 'advancing', 'blocked'].includes(child.state)) throw Error('New version 3 cases must start from unfulfilled prior intentions');
        if (item.initialBusinessStatus === 'planned' && (target.modality !== 'intent' || target.states.some(state => ['resolved', 'fulfilled'].includes(state)))) throw Error('Planned business status cannot admit an established or fulfilled child; fix the fixture before dispatch');
      }
    }
  }
  return sourceText;
}

export function narrativeStoryModelInput(corpus, sourceText) {
  return { title: corpus.title, sourceText, actors: corpus.actors, objectName: corpus.objectName,
    supportingFact: corpus.supportingFact, knowledgeSeed: corpus.knowledgeSeed,
    cases: corpus.cases.map(({ id, title, table, text, instruction, initialBusinessStatus, initialDevelopments }) => ({ id, title, table, text, instruction,
      initialBusinessStatus: corpus.version === 3 ? initialBusinessStatus : undefined,
      initialDevelopments: initialDevelopments?.map(({ id, statement, developmentType, state, modality }) => ({ id, statement, developmentType, state, modality })) })) };
}

import test from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { validateNarrativeStoryCorpus, narrativeStoryModelInput } from './narrative-candidate-story-contract.mjs';
const base = new URL('../tests/acceptance/narrative-world/', import.meta.url);
const fresh = () => JSON.parse(readFileSync(new URL('target-state-independent-story-corpus-20261015-v1.json', base)));
const source = readFileSync(new URL(fresh().sourceFile, base));

test('new complete-story corpus admits mixed outcomes only with explicit compatible business state', () => {
  const corpus = fresh();
  assert.equal(validateNarrativeStoryCorpus(corpus, source), source.toString('utf8'));
  corpus.cases[0].initialBusinessStatus = 'planned';
  assert.throws(() => validateNarrativeStoryCorpus(corpus, source), /cannot admit/);
  delete corpus.cases[0].initialBusinessStatus;
  assert.throws(() => validateNarrativeStoryCorpus(corpus, source), /business status/);
});
test('model transport strips expected answers, including unexpected fields on prior children', () => {
  const corpus = fresh(); corpus.cases[0].expected.privateGold = 'gold-do-not-send';
  corpus.cases[0].initialDevelopments[0].expected = 'gold-do-not-send';
  const input = narrativeStoryModelInput(corpus, source.toString('utf8'));
  assert.equal(input.cases[0].initialBusinessStatus, 'planted');
  assert.equal(input.cases[0].initialDevelopments.length, 2);
  assert.equal(input.sourceText, source.toString('utf8'));
  assert.ok(!JSON.stringify(input).includes('gold-do-not-send'));
  assert.ok(!Object.hasOwn(input.cases[0], 'expected'));
});
test('source mutation, nonverbatim excerpt, duplicate identity and leaked completed initial state fail before dispatch', () => {
  assert.throws(() => validateNarrativeStoryCorpus(fresh(), Buffer.concat([source, Buffer.from('\n')])), /hash mismatch/);
  const excerpt = fresh(); excerpt.cases[0].text = '这是分析而不是故事原文';
  assert.throws(() => validateNarrativeStoryCorpus(excerpt, source), /not verbatim/);
  const duplicate = fresh(); duplicate.cases[0].initialDevelopments[1].id = duplicate.cases[0].initialDevelopments[0].id;
  assert.throws(() => validateNarrativeStoryCorpus(duplicate, source), /distinct prior children/);
  const leaked = fresh(); leaked.cases[0].initialDevelopments[1].state = 'fulfilled';
  assert.throws(() => validateNarrativeStoryCorpus(leaked, source), /unfulfilled prior intentions/);
});
test('historical v2 rejected case retains its original contract and planted is not silently injected', () => {
  const corpus = JSON.parse(readFileSync(new URL('target-state-story-corpus-20261015-v1.json', base)));
  const oldSource = readFileSync(new URL(corpus.sourceFile, base));
  validateNarrativeStoryCorpus(corpus, oldSource);
  corpus.cases[0].initialBusinessStatus = 'planted';
  assert.equal(narrativeStoryModelInput(corpus, oldSource.toString('utf8')).cases[0].initialBusinessStatus, undefined);
});

scripts/narrative-impact-contract.mjs.source:
import { sha256, estimateReaderTokens } from './narrative-reader-contract.mjs'

export const IMPACT_ENTRY_ID = 'eval.narrative-world.edit-impact'
const DISPOSITIONS = ['review', 'uncertain', 'no-specific-impact']
const exact = (value, keys) => value && typeof value === 'object' && !Array.isArray(value)
  && Object.keys(value).sort().join(',') === [...keys].sort().join(',')

export const IMPACT_SCHEMA = {
  type: 'object', additionalProperties: false, required: ['recommendations'], properties: {
    recommendations: { type: 'array', items: { type: 'object', additionalProperties: false,
      required: ['sourceId', 'disposition', 'reason', 'evidence'], properties: {
        sourceId: { type: 'string' }, disposition: { type: 'string', enum: DISPOSITIONS }, reason: { type: 'string' },
        evidence: { type: 'array', items: { type: 'object', additionalProperties: false,
          required: ['sourceId', 'quote'], properties: { sourceId: { type: 'string' }, quote: { type: 'string' } } } },
      } } },
  },
}

export function validateImpactProtocol(protocol) {
  const limits = ['maxInputBytes', 'maxEstimatedInputTokens', 'maxObservedInputTokens', 'maxObservedOutputTokens',
    'maxReasonCharacters', 'maxEvidencePerRecommendation', 'maxQuoteCharacters', 'timeoutMs']
  const knownVersion = protocol.version === 1 ? protocol.failurePolicy === 'stop-no-retry'
    : protocol.version === 2 && protocol.failurePolicy === 'stop-transport-budget-unknown;continue-complete-invalid-no-retry'
      && protocol.quotableSources === 'original-text-and-after-text-only'
  if (protocol.schema !== 'storyforge.narrative-impact-model-protocol' || !knownVersion
    || protocol.entryId !== IMPACT_ENTRY_ID || protocol.provider !== 'local-codex-subscription'
    || protocol.model !== 'gpt-6.1-sol' || protocol.reasoningEffort !== 'medium'
    || protocol.retries !== 0 || protocol.concurrency !== 2 || protocol.pilotActualCalls !== 8
    || protocol.caseCount !== 48 || protocol.familyCount !== 12 || protocol.holdoutFamilyCount !== 4
    || typeof protocol.systemPrompt !== 'string' || !protocol.systemPrompt.trim()
    || limits.some(key => !Number.isSafeInteger(protocol.budget?.[key]) || protocol.budget[key] < 1)
    || protocol.budget.timeoutMs > 300000 || protocol.budget.serverEnforcedOutputTokenLimit !== null
    || protocol.accepted !== false || protocol.independentHumanReviews !== 0
    || protocol.costUsd !== null) {
    throw Error('Unknown or unbounded impact evaluation protocol')
  }
  return protocol
}

/** Sources and the proposed textual edit only. Gold, edit kinds and split
 * labels are deliberately not read while building model-visible material. */
export function impactRequest(family, edit, protocol) {
  validateImpactProtocol(protocol)
  const sources = family.sources.filter(source => source.branch === 'canon' && source.kind !== 'hypothesis')
  if (!sources.length || new Set(sources.map(source => source.id)).size !== sources.length
    || sources.some(source => typeof source.text !== 'string' || typeof source.title !== 'string')) throw Error('Invalid original source set')
  const changed = sources.find(source => source.id === edit.sourceId)
  if (!changed || changed.kind !== 'chapter' || typeof edit.before !== 'string' || !edit.before
    || typeof edit.after !== 'string' || edit.before === edit.after
    || changed.text.split(edit.before).length !== 2) throw Error('Edit must replace exactly one original chapter span')
  const documents = sources.map((source, index) => ({ sourceId: `S${index + 1}`, kind: source.kind,
    title: source.title, narrativeOrder: source.kind === 'chapter' ? source.order : null, text: source.text }))
  const sourceMap = Object.fromEntries(documents.map((document, index) => [document.sourceId, sources[index].id]))
  const changedSourceId = documents[sources.indexOf(changed)].sourceId
  const targetSourceIds = documents.filter(document => document.kind === 'chapter' && document.sourceId !== changedSourceId).map(document => document.sourceId)
  if (targetSourceIds.length !== 3) throw Error('Expected the original four-chapter family')
  // This is the pre-existing fixture author's locked knowledge record, not
  // the edit's scoring label and not an inferred universal world rule.
  const holder = sources.find(source => source.id === `${family.id}:character-b`)
  const lockSource = sources.find(source => source.id === `${family.id}:chapter-1`)
  const lockedQuote = family.seed?.lockedQuote
  if (!holder || typeof lockedQuote !== 'string' || !lockedQuote || !lockSource?.text.includes(lockedQuote)) {
    throw Error('Existing locked fixture statement has no original source')
  }
  const afterText = changed.text.replace(edit.before, edit.after)
  const payload = {
    task: '逐项判断这次草稿修改后，其余章节是否值得作者复核。输出只作为建议，不更改任何内容或锁定记录。',
    scope: { owner: 'isolated-synthetic-evaluation', perspective: 'author', branch: 'canon' },
    storyBefore: documents,
    proposedEdit: { sourceId: changedSourceId, before: edit.before, after: edit.after,
      fullTextAfter: { sourceId: 'AFTER', text: afterText } },
    protectedFact: { sourceId: 'LOCK', holderSourceId: documents[sources.indexOf(holder)].sourceId,
      predicate: 'knows', value: lockedQuote, locked: true,
      declaration: '测试作者已确认并锁定这条人物知识记录；草稿改写不自动更改它。',
      originalSourceId: documents[sources.indexOf(lockSource)].sourceId },
    targetSourceIds,
  }
  if (protocol.version === 2) {
    // The protected knowledge record is an author constraint, not another
    // prose source. Its evidence remains in the original chapter text.
    const { sourceId: _sourceId, declaration, ...record } = payload.protectedFact
    payload.protectedFact = record
    payload.nonEvidenceNotes = { protectedKnowledge: declaration }
  }
  const messages = [{ role: 'system', content: protocol.systemPrompt }, { role: 'user', content: JSON.stringify(payload) }]
  const encoded = JSON.stringify(messages), inputBytes = Buffer.byteLength(encoded), estimatedInputTokens = estimateReaderTokens(encoded)
  if (inputBytes > protocol.budget.maxInputBytes || estimatedInputTokens > protocol.budget.maxEstimatedInputTokens) {
    throw Error('Impact input exceeds fixed budget; source text must not be truncated')
  }
  return { messages, promptHash: sha256(messages), inputBytes, estimatedInputTokens, sourceMap, targetSourceIds, changedSourceId,
    referenceTexts: { ...Object.fromEntries(documents.map(document => [document.sourceId, document.text])), AFTER: afterText,
      ...(protocol.version === 1 ? { LOCK: lockedQuote } : {}) } }
}

export function prepareImpactCases(corpus, protocol) {
  validateImpactProtocol(protocol)
  if (!Array.isArray(corpus.families) || corpus.families.length !== protocol.familyCount
    || new Set(corpus.families.map(family => family.id)).size !== protocol.familyCount
    || corpus.families.filter(family => family.split === 'holdout').length !== protocol.holdoutFamilyCount
    || corpus.families.some(family => !['development', 'holdout'].includes(family.split))) throw Error('Incomplete original family partition')
  const cases = corpus.families.flatMap(family => family.edits.map(edit => ({ id: edit.id, familyId: family.id,
    split: family.split, kind: edit.kind, request: impactRequest(family, edit, protocol) })))
  if (cases.length !== protocol.caseCount || new Set(cases.map(item => item.id)).size !== cases.length
    || new Set(cases.map(item => item.request.promptHash)).size !== cases.length) throw Error('Duplicate or incomplete original edit matrix')
  const pilot = [], seen = new Set()
  for (const split of ['development', 'holdout']) for (const kind of ['semantic', 'cosmetic', 'locked-rule', 'knowledge-timing']) {
    const first = cases.filter(item => item.split === split && item.kind === kind)
      .sort((a, b) => a.request.promptHash.localeCompare(b.request.promptHash))[0]
    if (!first) throw Error('Missing edit kind in a fixed split')
    pilot.push(first); seen.add(first.id)
  }
  return [...pilot, ...cases.filter(item => !seen.has(item.id)).sort((a, b) => a.request.promptHash.localeCompare(b.request.promptHash))]
}

export function validateImpactAnswer(text, prepared, protocol) {
  const result = JSON.parse(text), limit = protocol.budget
  if (!exact(result, ['recommendations']) || !Array.isArray(result.recommendations)
    || result.recommendations.length !== prepared.targetSourceIds.length) throw Error('Incomplete impact recommendation set')
  const seen = new Set()
  for (const item of result.recommendations) {
    if (!exact(item, ['sourceId', 'disposition', 'reason', 'evidence'])
      || !prepared.targetSourceIds.includes(item.sourceId) || seen.has(item.sourceId)
      || !DISPOSITIONS.includes(item.disposition) || typeof item.reason !== 'string' || !item.reason.trim()
      || [...item.reason].length > limit.maxReasonCharacters || !Array.isArray(item.evidence)
      || item.evidence.length < 2 || item.evidence.length > limit.maxEvidencePerRecommendation) throw Error('Invalid impact recommendation')
    seen.add(item.sourceId)
    for (const evidence of item.evidence) {
      if (!exact(evidence, ['sourceId', 'quote']) || typeof evidence.sourceId !== 'string'
        || typeof evidence.quote !== 'string' || !evidence.quote.trim() || [...evidence.quote].length > limit.maxQuoteCharacters
        || !Object.hasOwn(prepared.referenceTexts, evidence.sourceId)
        || !prepared.referenceTexts[evidence.sourceId].includes(evidence.quote)) throw Error('Impact evidence does not match its named frozen source')
    }
    if (!item.evidence.some(evidence => evidence.sourceId === item.sourceId)
      || !item.evidence.some(evidence => evidence.sourceId === prepared.changedSourceId || evidence.sourceId === 'AFTER')) {
      throw Error('Impact explanation must cite both its target chapter and the edited chapter')
    }
  }
  return result
}

export function impactUsageWithinBudget(usage, protocol) {
  return !!usage && Number.isSafeInteger(usage.inputTokens) && usage.inputTokens >= 0
    && Number.isSafeInteger(usage.outputTokens) && usage.outputTokens >= 0
    && usage.inputTokens <= protocol.budget.maxObservedInputTokens && usage.outputTokens <= protocol.budget.maxObservedOutputTokens
}

/** Protocol v2 may retain a known completed invalid output without scoring or
 * repeating it. Transport, budget and unknown outcomes never qualify. */
export function isRetainedInvalidImpactCall(result, prepared, protocol) {
  if (protocol.version !== 2
    || protocol.failurePolicy !== 'stop-transport-budget-unknown;continue-complete-invalid-no-retry'
    || result?.status !== 'invalid-output' || result.failureStage !== 'output-contract'
    || result.promptHash !== prepared.promptHash || result.provider !== protocol.provider || result.model !== protocol.model
    || result.dispatched !== true || result.generationCompleted !== true || Object.hasOwn(result, 'answer')
    || typeof result.rawText !== 'string' || !impactUsageWithinBudget(result.usage, protocol)) return false
  try { validateImpactAnswer(result.rawText, prepared, protocol) } catch { return true }
  return false
}

/** Fully persisted successes, and v2 known-invalid receipts, can be retained.
 * Neither is resent. Unknown, transport and budget failures block resume. */
export function validatePriorImpactCall(prior, prepared, protocol) {
  const { started, request, result } = prior ?? {}
  if (!started || !request || !result || started.promptHash !== prepared.promptHash
    || started.model !== protocol.model || request.promptHash !== prepared.promptHash
    || request.model !== protocol.model || sha256(request.messages) !== prepared.promptHash
    || sha256(request.outputSchema) !== sha256(IMPACT_SCHEMA)
    || result.promptHash !== prepared.promptHash || result.provider !== protocol.provider || result.model !== protocol.model
    || result.dispatched !== true || result.generationCompleted !== true
    || !impactUsageWithinBudget(result.usage, protocol)) throw Error('Prior impact call is missing, failed, unknown or incompatible; no replay')
  if (isRetainedInvalidImpactCall(result, prepared, protocol)) return result
  if (result.status !== 'completed') throw Error('Prior impact call is not a retainable terminal receipt; no replay')
  const validated = validateImpactAnswer(result.rawText, prepared, protocol)
  if (sha256(validated) !== sha256(result.answer)) throw Error('Prior impact output changed; no replay')
  return result
}

/** A result filename alone is not a usable receipt: interrupted writes may
 * leave a partial file. Only results actually loaded or persisted count. */
export function impactMissingResultHashes(cases, files, results) {
  return cases.filter(item => files.has(`${item.request.promptHash}.started.json`)
    && !results.has(item.request.promptHash)).map(item => item.request.promptHash)
}

/** Gold is first inspected here, after an actual output has been validated.
 * Uncertain recommendations are counted as review, never hidden as skips. */
export function scoreImpactSuggestion(edit, prepared, answer) {
  const expected = [...edit.mustReview].sort(), forbidden = [...edit.mustNotReview].sort()
  const targetIds = prepared.targetSourceIds.map(id => prepared.sourceMap[id]), universe = new Set([...expected, ...forbidden])
  if (new Set(expected).size !== expected.length || new Set(forbidden).size !== forbidden.length
    || expected.some(id => forbidden.includes(id)) || [...universe].some(id => !targetIds.includes(id))) throw Error('Invalid separate edit gold')
  const predicted = answer.recommendations.filter(item => item.disposition !== 'no-specific-impact').map(item => prepared.sourceMap[item.sourceId]).sort()
  const scored = predicted.filter(id => universe.has(id))
  return { expected, mustNotReview: forbidden, predicted: scored, unscoredPredictions: predicted.filter(id => !universe.has(id)),
    truePositive: scored.filter(id => expected.includes(id)).length, falsePositive: scored.filter(id => forbidden.includes(id)).length,
    falseNegative: expected.filter(id => !scored.includes(id)).length,
    uncertainRecommendations: answer.recommendations.filter(item => item.disposition === 'uncertain').length }
}

export function summarizeImpactSuggestions(rows) {
  const metrics = selected => {
    const sum = field => selected.reduce((total, row) => total + row.score[field], 0)
    const truePositive = sum('truePositive'), falsePositive = sum('falsePositive'), falseNegative = sum('falseNegative')
    return { cases: selected.length, truePositive, falsePositive, falseNegative,
      precision: truePositive + falsePositive ? truePositive / (truePositive + falsePositive) : null,
      recall: truePositive + falseNegative ? truePositive / (truePositive + falseNegative) : null,
      uncertainRecommendations: sum('uncertainRecommendations'),
      unscoredPredictions: selected.reduce((total, row) => total + row.score.unscoredPredictions.length, 0) }
  }
  const by = field => Object.fromEntries([...new Set(rows.map(row => row[field]))].sort().map(key => [key, metrics(rows.filter(row => row[field] === key))]))
  return { overall: metrics(rows), byKind: by('kind'), bySplit: by('split'), byFamily: by('familyId'),
    boundary: 'Model suggestions on the original synthetic edit corpus. Exact quotes prove source presence, not entailment. No deterministic dependency, unaffected certificate, author decision, production replacement or acceptance is inferred.' }
}

scripts/narrative-impact-contract.test.m.source:
import { test } from 'node:test'
import assert from 'node:assert/strict'
import { readFileSync } from 'node:fs'
import { sha256 } from './narrative-reader-contract.mjs'
import { IMPACT_SCHEMA, impactRequest, prepareImpactCases, validateImpactProtocol,
  validateImpactAnswer, validatePriorImpactCall, isRetainedInvalidImpactCall, impactMissingResultHashes, impactUsageWithinBudget, scoreImpactSuggestion, summarizeImpactSuggestions } from './narrative-impact-contract.mjs'

const corpus = JSON.parse(readFileSync(new URL('../tests/acceptance/narrative-world/corpus-v1.json', import.meta.url)))
const protocol = JSON.parse(readFileSync(new URL('../tests/acceptance/narrative-world/impact-model-protocol-20261015-v1.json', import.meta.url)))
const protocolV2 = JSON.parse(readFileSync(new URL('../tests/acceptance/narrative-world/impact-model-protocol-20261015-v2.json', import.meta.url)))
const family = corpus.families[0], edit = family.edits[0], request = impactRequest(family, edit, protocol)
const quote = text => [...text].slice(0, 35).join('')
const answer = () => ({ recommendations: request.targetSourceIds.map(sourceId => ({ sourceId, disposition: 'no-specific-impact',
  reason: '仅为合同反例使用的合成回答，不是模型证据。', evidence: [
    { sourceId, quote: quote(request.referenceTexts[sourceId]) }, { sourceId: 'AFTER', quote: quote(request.referenceTexts.AFTER) },
  ] })) })
const validate = value => validateImpactAnswer(JSON.stringify(value), request, protocol)

test('all 48 original edits freeze in the original 8/4 family partition with a blind stratified pilot', () => {
  const prepared = prepareImpactCases(corpus, protocol)
  assert.equal(prepared.length, 48)
  assert.equal(new Set(prepared.map(row => row.request.promptHash)).size, 48)
  assert.equal(new Set(prepared.filter(row => row.split === 'holdout').map(row => row.familyId)).size, 4)
  assert.equal(new Set(prepared.slice(0, 8).map(row => `${row.split}/${row.kind}`)).size, 8)
  for (const row of prepared) assert.equal(row.request.targetSourceIds.length, 3)
})

test('gold, edit kind, split and scoring rationale cannot alter model messages', () => {
  const copied = structuredClone(family), target = copied.edits[0]
  copied.split = 'POISON-SPLIT'; copied.queries = [{ answerAtoms: ['POISON-ANSWER'] }]
  Object.assign(target, { kind: 'POISON-KIND', mustReview: ['POISON-REVIEW'], mustNotReview: ['POISON-SKIP'],
    rationale: 'POISON-RATIONALE', dependencyEvidence: [{ quote: 'POISON-DEPENDENCY' }], protectedFact: 'POISON-PROTECTED' })
  copied.seed.truth = 'POISON-TRUTH'; copied.seed.belief = 'POISON-BELIEF'; copied.seed.plannedText = 'POISON-PLAN'
  assert.deepEqual(impactRequest(copied, target, protocol).messages, request.messages)
  assert.doesNotMatch(JSON.stringify(request.messages), /mustReview|mustNotReview|dependencyEvidence|answerAtoms|POISON/)
})

test('the locked statement is explicit existing fixture knowledge with an original source, not elevated Canon', () => {
  const payload = JSON.parse(request.messages[1].content)
  assert.equal(payload.protectedFact.predicate, 'knows')
  assert.equal(payload.protectedFact.value, family.seed.lockedQuote)
  assert.equal(payload.protectedFact.locked, true)
  assert(payload.storyBefore.find(source => source.sourceId === payload.protectedFact.originalSourceId).text.includes(payload.protectedFact.value))
  const bad = structuredClone(family); bad.seed.lockedQuote = '无原文依据的规则'
  assert.throws(() => impactRequest(bad, bad.edits[0], protocol), /original source/)
})

test('whole original sources and edited full text are retained; other branches never enter the request', () => {
  const payload = JSON.parse(request.messages[1].content)
  const sources = family.sources.filter(source => source.branch === 'canon' && source.kind !== 'hypothesis')
  assert.deepEqual(payload.storyBefore.map(source => source.text), sources.map(source => source.text))
  const source = family.sources.find(source => source.id === edit.sourceId)
  assert.equal(payload.proposedEdit.fullTextAfter.text, source.text.replace(edit.before, edit.after))
  assert(!request.targetSourceIds.includes(request.changedSourceId))
  const small = structuredClone(protocol); small.budget.maxInputBytes = 100
  assert.throws(() => impactRequest(family, edit, small), /must not be truncated/)
})

test('ambiguous, absent and no-op replacements are refused before a call', () => {
  assert.throws(() => impactRequest(family, { ...edit, before: 'not-in-original' }, protocol), /exactly one/)
  assert.throws(() => impactRequest(family, { ...edit, after: edit.before }, protocol), /exactly one/)
  const duplicate = structuredClone(family); duplicate.sources.find(source => source.id === edit.sourceId).text += edit.before
  assert.throws(() => impactRequest(duplicate, edit, protocol), /exactly one/)
})

test('the output contract accepts exactly one recommendation for each target', () => {
  assert.deepEqual(validate(answer()), answer())
  assert.equal(IMPACT_SCHEMA.additionalProperties, false)
  const omitted = answer(); omitted.recommendations.pop(); assert.throws(() => validate(omitted), /Incomplete/)
  const duplicate = answer(); duplicate.recommendations[1].sourceId = duplicate.recommendations[0].sourceId
  assert.throws(() => validate(duplicate), /Invalid/)
  const foreign = answer(); foreign.recommendations[0].sourceId = 'OTHER-WORK'
  assert.throws(() => validate(foreign), /Invalid/)
  const self = answer(); self.recommendations[0].sourceId = request.changedSourceId
  assert.throws(() => validate(self), /Invalid/)
})

test('each recommendation cites both the target and the modified source with exact named quotes', () => {
  const fabricated = answer(); fabricated.recommendations[0].evidence[0].quote = '不存在的原文'
  assert.throws(() => validate(fabricated), /named frozen source/)
  const wrong = answer(); wrong.recommendations[0].evidence[0].sourceId = request.targetSourceIds[1]
  assert.throws(() => validate(wrong), /named frozen source/)
  const noTarget = answer(); noTarget.recommendations[0].evidence = [noTarget.recommendations[0].evidence[1], noTarget.recommendations[0].evidence[1]]
  assert.throws(() => validate(noTarget), /both/)
  const noChange = answer(); noChange.recommendations[0].evidence = [noChange.recommendations[0].evidence[0], noChange.recommendations[0].evidence[0]]
  assert.throws(() => validate(noChange), /both/)
})

test('model output cannot introduce a write action or deterministic unaffected certificate', () => {
  assert.throws(() => validate({ ...answer(), adopt: true }), /Incomplete/)
  const write = answer(); write.recommendations[0].disposition = 'delete'
  assert.throws(() => validate(write), /Invalid/)
  const certificate = answer(); certificate.recommendations[0].disposition = 'unaffected'
  assert.throws(() => validate(certificate), /Invalid/)
  const long = answer(); long.recommendations[0].reason = '字'.repeat(protocol.budget.maxReasonCharacters + 1)
  assert.throws(() => validate(long), /Invalid/)
})

test('a lock declaration is metadata and cannot substitute for its evidence text', () => {
  const payload = JSON.parse(request.messages[1].content)
  const value = answer()
  value.recommendations[0].evidence.push({ sourceId: 'LOCK', quote: payload.protectedFact.declaration })
  assert.throws(() => validate(value), /named frozen source/)
  value.recommendations[0].evidence.at(-1).quote = payload.protectedFact.value
  assert.deepEqual(validate(value), value)
})

test('uncertainty remains a predicted review and missing positive suggestions remain false negatives', () => {
  const value = answer()
  value.recommendations[0].disposition = 'uncertain'
  validate(value)
  const targetIds = request.targetSourceIds.map(id => request.sourceMap[id])
  const gold = { mustReview: [targetIds[1]], mustNotReview: [targetIds[0]], unrelatedGold: 'ignored' }
  const score = scoreImpactSuggestion(gold, request, value)
  assert.equal(score.falsePositive, 1); assert.equal(score.falseNegative, 1)
  assert.equal(score.uncertainRecommendations, 1)
  assert.throws(() => scoreImpactSuggestion({ mustReview: ['other-owner'], mustNotReview: [] }, request, value), /Invalid separate/)
})

test('unscored predictions are disclosed rather than counted as scored successes or dropped', () => {
  const value = answer(); value.recommendations[2].disposition = 'review'
  const target = request.sourceMap[request.targetSourceIds[0]]
  const score = scoreImpactSuggestion({ mustReview: [], mustNotReview: [target] }, request, value)
  assert.equal(score.unscoredPredictions.length, 1)
  const summary = summarizeImpactSuggestions([{ id: 'example', familyId: 'family', split: 'holdout', kind: 'cosmetic', score }])
  assert.equal(summary.overall.precision, null); assert.equal(summary.overall.recall, null)
  assert.equal(summary.overall.unscoredPredictions, 1)
})

test('budget, model, retry and acceptance boundaries are checked before dispatch', () => {
  assert.equal(validateImpactProtocol(protocol), protocol)
  for (const change of [{ model: 'another-model' }, { retries: 1 }, { concurrency: 3 }, { accepted: true }, { independentHumanReviews: 1 }]) {
    assert.throws(() => validateImpactProtocol({ ...protocol, ...change }), /Unknown/)
  }
  assert.equal(impactUsageWithinBudget({ inputTokens: 1000, outputTokens: 100 }, protocol), true)
  for (const usage of [null, {}, { inputTokens: -1, outputTokens: 0 }, { inputTokens: 1, outputTokens: Infinity },
    { inputTokens: protocol.budget.maxObservedInputTokens + 1, outputTokens: 0 }]) assert.equal(impactUsageWithinBudget(usage, protocol), false)
})

test('missing families or repeated edit identities cannot form a complete experiment', () => {
  const missing = structuredClone(corpus); missing.families.pop()
  assert.throws(() => prepareImpactCases(missing, protocol), /Incomplete/)
  const duplicate = structuredClone(corpus); duplicate.families[0].edits[1].id = duplicate.families[0].edits[0].id
  assert.throws(() => prepareImpactCases(duplicate, protocol), /Duplicate/)
})

test('resume only reuses a complete identity-bound success and never replays unknown or failed attempts', () => {
  const prior = () => ({ started: { promptHash: request.promptHash, model: protocol.model },
    request: { promptHash: request.promptHash, model: protocol.model, messages: structuredClone(request.messages), outputSchema: structuredClone(IMPACT_SCHEMA) },
    result: { promptHash: request.promptHash, provider: protocol.provider, model: protocol.model, status: 'completed',
      dispatched: true, generationCompleted: true, usage: { inputTokens: 1000, outputTokens: 100 }, rawText: JSON.stringify(answer()), answer: answer() } })
  const valid = prior(); assert.equal(validatePriorImpactCall(valid, request, protocol), valid.result)
  for (const field of ['started', 'request', 'result']) {
    const missing = prior(); delete missing[field]
    assert.throws(() => validatePriorImpactCall(missing, request, protocol), /no replay/)
  }
  for (const status of ['failed', 'invalid-output', 'unknown-or-interrupted', 'running']) {
    const failure = prior(); failure.result.status = status
    assert.throws(() => validatePriorImpactCall(failure, request, protocol), /no replay/)
  }
  for (const change of [value => { value.started.model = 'another-model' },
    value => { value.request.messages[1].content += 'changed' }, value => { value.result.usage = null },
    value => { value.result.generationCompleted = false }, value => { value.result.answer.recommendations[0].reason = 'changed' }]) {
    const altered = prior(); change(altered)
    assert.throws(() => validatePriorImpactCall(altered, request, protocol), /no replay/)
  }
})

test('a partial result file remains an unknown attempt instead of an unattempted input', () => {
  const cases = ['complete', 'partial', 'no-result', 'unstarted'].map(promptHash => ({ request: { promptHash } }))
  const files = new Set(['complete.started.json', 'complete.result.json', 'partial.started.json',
    'partial.result.json', 'no-result.started.json', 'unstarted.request.json'])
  const results = new Map([['complete', { status: 'completed' }]])
  assert.deepEqual(impactMissingResultHashes(cases, files, results), ['partial', 'no-result'])
})

test('v1 archived inputs remain byte-identical while v2 gives all 48 requests new identities', () => {
  const old = prepareImpactCases(corpus, protocol), next = prepareImpactCases(corpus, protocolV2)
  assert.equal(sha256(old.map(item => item.request.messages)), '7f9e1de8d26a0f43e6947dcdbca1365ed695d14ec27581ef80e5dd9f4b2b08f1')
  assert.equal(next.length, 48)
  assert.equal(new Set(next.slice(0, 8).map(item => `${item.split}/${item.kind}`)).size, 8)
  assert(next.every(item => !old.some(previous => previous.request.promptHash === item.request.promptHash)))
  assert.throws(() => validateImpactProtocol({ ...protocolV2, failurePolicy: 'continue-every-error' }), /Unknown/)
  assert.throws(() => validateImpactProtocol({ ...protocolV2, quotableSources: 'all-metadata' }), /Unknown/)
})

test('v2 keeps complete story and protected knowledge but only original and AFTER text can be quoted', () => {
  const next = impactRequest(family, edit, protocolV2), oldPayload = JSON.parse(request.messages[1].content)
  const payload = JSON.parse(next.messages[1].content)
  assert.deepEqual(payload.storyBefore, oldPayload.storyBefore)
  assert.deepEqual(payload.proposedEdit, oldPayload.proposedEdit)
  assert.equal(payload.protectedFact.value, oldPayload.protectedFact.value)
  assert.equal(payload.protectedFact.predicate, 'knows')
  assert.equal(payload.protectedFact.sourceId, undefined)
  assert.equal(payload.protectedFact.declaration, undefined)
  assert.equal(payload.nonEvidenceNotes.protectedKnowledge, oldPayload.protectedFact.declaration)
  assert.equal(Object.hasOwn(next.referenceTexts, 'LOCK'), false)
  assert.deepEqual(validateImpactAnswer(JSON.stringify(answer()), next, protocolV2), answer())
  for (const evidence of [{ sourceId: 'LOCK', quote: payload.protectedFact.value },
    { sourceId: 'S1', quote: payload.nonEvidenceNotes.protectedKnowledge }]) {
    const bad = answer(); bad.recommendations[0].evidence.push(evidence)
    assert.throws(() => validateImpactAnswer(JSON.stringify(bad), next, protocolV2), /named frozen source/)
  }
})

test('v2 rendering still excludes gold, rationale, split and edit-category labels', () => {
  const copied = structuredClone(family), target = copied.edits[0]
  copied.split = 'POISON-SPLIT'; copied.queries = [{ answerAtoms: ['POISON-ANSWER'] }]
  Object.assign(target, { kind: 'POISON-KIND', mustReview: ['POISON-REVIEW'], mustNotReview: ['POISON-SKIP'],
    rationale: 'POISON-RATIONALE', dependencyEvidence: [{ quote: 'POISON-DEPENDENCY' }] })
  assert.deepEqual(impactRequest(copied, target, protocolV2).messages, impactRequest(family, edit, protocolV2).messages)
})

const requestV2 = impactRequest(family, edit, protocolV2)
const invalidPriorV2 = () => {
  const bad = answer()
  bad.recommendations[0].evidence.push({ sourceId: 'LOCK', quote: family.seed.lockedQuote })
  return { started: { promptHash: requestV2.promptHash, model: protocolV2.model },
    request: { promptHash: requestV2.promptHash, model: protocolV2.model, messages: requestV2.messages, outputSchema: IMPACT_SCHEMA },
    result: { promptHash: requestV2.promptHash, model: protocolV2.model, provider: protocolV2.provider,
      status: 'invalid-output', failureStage: 'output-contract', dispatched: true, generationCompleted: true,
      usage: { inputTokens: 1000, outputTokens: 100 }, rawText: JSON.stringify(bad) } }
}

test('v2 retains a complete invalid receipt as ungraded and excludes its identity from pending calls', () => {
  const prior = invalidPriorV2()
  assert.equal(isRetainedInvalidImpactCall(prior.result, requestV2, protocolV2), true)
  assert.equal(validatePriorImpactCall(prior, requestV2, protocolV2), prior.result)
  const retained = new Map([[requestV2.promptHash, prior.result]])
  assert.equal(prepareImpactCases(corpus, protocolV2).filter(item => !retained.has(item.request.promptHash)).length, 47)
  assert.equal(isRetainedInvalidImpactCall(prior.result, requestV2, protocol), false)
})

test('v2 cannot continue transport, budget, unknown or incomplete calls by relabeling them invalid', () => {
  for (const change of [{ status: 'failed' }, { failureStage: 'transport' }, { status: 'unknown-or-interrupted' },
    { dispatched: false }, { generationCompleted: false }, { usage: null },
    { usage: { inputTokens: 30001, outputTokens: 100 } }, { promptHash: 'foreign-input' }]) {
    const prior = invalidPriorV2(); Object.assign(prior.result, change)
    assert.equal(isRetainedInvalidImpactCall(prior.result, requestV2, protocolV2), false)
    assert.throws(() => validatePriorImpactCall(prior, requestV2, protocolV2), /no replay/)
  }
})

test('invalid receipts cannot carry a scored answer or silently become valid during resume', () => {
  for (const change of [{ answer: answer() }, { rawText: JSON.stringify(answer()) }, { rawText: null }]) {
    const prior = invalidPriorV2(); Object.assign(prior.result, change)
    assert.equal(isRetainedInvalidImpactCall(prior.result, requestV2, protocolV2), false)
    assert.throws(() => validatePriorImpactCall(prior, requestV2, protocolV2), /no replay/)
  }
})

