  mkdirSync(resolve(directory, 'calls'), { recursive: true })
  const write = (name, value) => writeFileSync(resolve(directory, name), JSON.stringify(value, null, 2) + '\n')
  const preflight = { version: 2, dispatchAllowed: true }
