import { test } from 'node:test'
import assert from 'node:assert/strict'
import { readFileSync } from 'node:fs'
import { judgeRequest, judgeOutputSchema, validateJudgeProtocol, validateJudgeAnswer,
  validatePriorJudgeCall, summarizeJudge, judgeExecutionCounts } from './narrative-reader-judge-contract.mjs'

const read = name => JSON.parse(readFileSync(new URL(`../tests/acceptance/narrative-world/${name}`, import.meta.url)))
const protocol = read('reader-judge-protocol-20261015-v2.json')
const legacy = read('reader-judge-protocol-20261015-v1.json')
const input = (status = 'insufficient', answer = '铜铃在阿澈手中。') => ({
  readerRequest: { messages: [{ role: 'user', content: JSON.stringify({ question: '铜铃在哪里？', operation: 'original-read',
    view: 'author', branch: 'canon', retrievalStatus: 'matched', diagnostics: [],
    documents: [{ documentId: 'D1', title: '第一幕', text: '铜铃在阿澈掌心。', atom: null, evidence: [] }] }) }] },
  readerAnswer: { status, answer, citations: [{ documentId: 'D1', quote: '铜铃在阿澈掌心。' }] },
  family: { sources: [{ id: 'scene', title: '第一幕', kind: 'chapter', branch: 'canon', text: '铜铃在阿澈掌心。' }] },
  question: { answerAtoms: ['铜铃在阿澈手中'], forbiddenAtom: null },
})
const judgment = () => ({ answerDisposition: 'substantive-answer', assessment: 'correct', answerCorrectness: 5,
  materialFaithfulness: 5, scopeCompliance: 'compliant', reason: '回答直接指出所在，材料支持这一改写。',
  evidence: [{ sourceId: 'answer', quote: '铜铃在阿澈手中。', relevance: '正文实质回答了地点问题。' },
    { sourceId: 'reader:D1', quote: '铜铃在阿澈掌心。', relevance: '实际获供材料支持其内容。' }] })

test('v2 pins its disposition and failure policy, without changing the v1 schema', () => {
  assert.equal(validateJudgeProtocol(protocol), protocol)
  assert.equal(judgeOutputSchema(legacy).properties.answerDisposition, undefined)
  assert.ok(judgeOutputSchema(protocol).properties.answerDisposition)
  for (const change of [{ retries: 1 }, { rubricVersion: 'other' },
    { failurePolicy: { ...protocol.failurePolicy, transportFailure: 'retry' } },
    { failurePolicy: { ...protocol.failurePolicy, extra: 'hidden' } }]) {
    assert.throws(() => validateJudgeProtocol({ ...protocol, ...change }))
  }
})
test('declared status stays in receipt metadata and never changes the content judge prompt', () => {
  const values = ['answered', 'insufficient', 'unsupported'].map(status => {
    const original = input(status), before = JSON.stringify(original), prepared = judgeRequest(original, protocol)
    const payload = JSON.parse(prepared.messages[1].content)
    assert.deepEqual(payload.response, { answer: original.readerAnswer.answer, citations: original.readerAnswer.citations })
    assert.equal(payload.referenceSources.find(source => source.sourceId === 'answer').value, original.readerAnswer.answer)
    assert.equal(prepared.readerStatus, status)
    assert.equal(JSON.stringify(original), before)
    return prepared
  })
  assert.equal(new Set(values.map(value => value.promptHash)).size, 1)
  assert.equal(validateJudgeAnswer(JSON.stringify(judgment()), values[1], protocol).answerCorrectness, 5)
})
test('the real causal counterexample is representable without retroactively accepting its rejected v1 rating', () => {
  const hash = '2b912ed54820752a26c14b67f937b52ea56f6d0652aed0231695eac9447aebb0'
  const prefix = `raw/reader-semantic-judge-20261015-v3/calls/${hash}`
  const sent = read(`${prefix}.request.json`), originalResult = read(`${prefix}.result.json`)
  const payload = JSON.parse(sent.messages[1].content)
  const data = { readerRequest: { messages: [{ role: 'user', content: JSON.stringify({ ...payload.task,
    retrievalStatus: payload.readerMaterial.status, diagnostics: payload.readerMaterial.diagnostics,
    documents: payload.readerMaterial.documents }) }] }, readerAnswer: payload.response,
  family: { sources: payload.referenceSources.filter(source => source.sourceId.startsWith('story:'))
    .map(source => ({ id: source.sourceId.slice(6), ...source.value })) }, question: payload.declaredAuditGold }
  assert.equal(data.readerAnswer.status, 'insufficient')
  assert.match(data.readerAnswer.answer, /不能据此建立因果关系/)
  assert.throws(() => validateJudgeAnswer(originalResult.rawText, judgeRequest(data, legacy), legacy), /Abstentions/)
  const representationOnly = { ...JSON.parse(originalResult.rawText), answerDisposition: 'substantive-answer' }
  assert.equal(validateJudgeAnswer(JSON.stringify(representationOnly), judgeRequest(data, protocol), protocol).answerDisposition, 'substantive-answer')
  assert.equal(read(`${prefix}.result.json`).status, 'failed')
})
test('a real abstention gets no correctness score even when its own status claims answered', () => {
  const answer = '无法判断铜铃所在位置。', prepared = judgeRequest(input('answered', answer), protocol)
  const value = { ...judgment(), answerDisposition: 'abstention', assessment: 'unjustified-abstention', answerCorrectness: null,
    evidence: [{ sourceId: 'answer', quote: answer, relevance: '未提供所求地点。' }] }
  assert.equal(validateJudgeAnswer(JSON.stringify(value), prepared, protocol).answerCorrectness, null)
  assert.throws(() => validateJudgeAnswer(JSON.stringify({ ...value, answerCorrectness: 5 }), prepared, protocol), /Abstentions/)
  assert.throws(() => validateJudgeAnswer(JSON.stringify({ ...value, assessment: 'correct' }), prepared, protocol), /disposition/)
})
test('content disposition needs a source-bound quote from the answer, not just supplied material', () => {
  const prepared = judgeRequest(input(), protocol)
  assert.throws(() => validateJudgeAnswer(JSON.stringify({ ...judgment(), evidence: [judgment().evidence[1]] }), prepared, protocol), /answer prose/)
  assert.throws(() => validateJudgeAnswer(JSON.stringify({ ...judgment(), evidence: [
    { ...judgment().evidence[1], sourceId: 'answer' }] }), prepared, protocol), /named frozen source/)
  assert.throws(() => validateJudgeAnswer(JSON.stringify({ ...judgment(), answerDisposition: 'cannot-grade' }), prepared, protocol), /disposition/)
})
test('unknown content and unknown faithfulness remain nullable rather than acquiring invented scores', () => {
  const prepared = judgeRequest(input(), protocol), value = { ...judgment(), answerDisposition: 'cannot-grade', assessment: 'cannot-grade',
    answerCorrectness: null, materialFaithfulness: null, scopeCompliance: 'uncertain', evidence: [] }
  assert.equal(validateJudgeAnswer(JSON.stringify(value), prepared, protocol).materialFaithfulness, null)
  assert.throws(() => validateJudgeAnswer(JSON.stringify({ ...judgment(), materialFaithfulness: null }), prepared, protocol))
})
test('metrics separate content disposition, declaration mismatch and shared observations', () => {
  const row = { condition: 'method', operation: 'read', split: 'holdout', judgePromptHash: 'one', readerReportedStatus: 'answered', judgment: judgment() }
  const refused = { ...row, judgePromptHash: 'two', judgment: { ...judgment(), answerDisposition: 'abstention', assessment: 'justified-abstention', answerCorrectness: null } }
  const metrics = summarizeJudge([row, { ...row, readerReportedStatus: 'insufficient' }, refused]).byCondition.method
  assert.equal(metrics.observations, 3); assert.equal(metrics.distinctGradedPrompts, 2)
  assert.equal(metrics.answeredAndGradable, 2); assert.equal(metrics.answerCorrectnessMedian, 5)
  assert.equal(metrics.statusComparable, 3); assert.equal(metrics.statusDisagreements, 2)
  assert.equal(metrics.declaredStatusMatrix.insufficient['substantive-answer'], 1)
  assert.equal(metrics.declaredStatusMatrix.answered.abstention, 1)
})
test('invalid judgments may be retained only with a completed generation, valid usage and a reproducible validation error', () => {
  const request = judgeRequest(input(), protocol), rawText = '{}'
  let validationError
  try { validateJudgeAnswer(rawText, request, protocol) } catch (error) { validationError = String(error) }
  const prior = { started: { promptHash: request.promptHash }, request: { promptHash: request.promptHash,
    model: protocol.model, messages: request.messages, outputSchema: judgeOutputSchema(protocol) }, result: {
    promptHash: request.promptHash, provider: protocol.provider, model: protocol.model, dispatched: true,
    generationCompleted: true, status: 'invalid-judgment', usage: { inputTokens: 50, outputTokens: 50 }, rawText, validationError } }
  assert.equal(validatePriorJudgeCall(prior, request, protocol).status, 'invalid-judgment')
  for (const changes of [{ generationCompleted: false }, { usage: null }, { dispatched: false },
    { validationError: 'different' }, { rawText: JSON.stringify(judgment()) }]) {
    assert.throws(() => validatePriorJudgeCall({ ...prior, result: { ...prior.result, ...changes } }, request, protocol))
  }
})
test('dispatch, invalid review, transport failure and pre-dispatch failure have distinct denominators', () => {
  const result = judgeExecutionCounts([{ dispatched: true, status: 'completed' }, { dispatched: true, status: 'invalid-judgment' },
    { dispatched: false, status: 'failed' }, { dispatched: true, status: 'failed' }, { dispatched: true, status: 'unknown-or-interrupted' }], 10)
  assert.deepEqual(result, { attemptedPrompts: 5, dispatchedActualCalls: 4, completedActualCalls: 1,
    invalidJudgmentActualCalls: 1, failedActualCalls: 2, preDispatchFailures: 1, notYetAttempted: 5, notYetCalled: 6, executionComplete: false })
  const closed = judgeExecutionCounts([{ dispatched: true, status: 'completed' }, { dispatched: true, status: 'invalid-judgment' }], 2)
  assert.equal(closed.executionComplete, true)
  assert.equal(closed.completedActualCalls, 1)
})

scripts/narrative-reader-judge-contract..source:
import { sha256, estimateReaderTokens } from './narrative-reader-contract.mjs'

export const JUDGE_ENTRY_ID = 'eval.narrative-world.reader-semantic-review'
export const ASSESSMENTS = ['correct', 'partly-correct', 'incorrect', 'justified-abstention', 'unjustified-abstention', 'cannot-grade']
export const JUDGE_SCHEMA = { type: 'object', additionalProperties: false,
  required: ['assessment', 'answerCorrectness', 'materialFaithfulness', 'scopeCompliance', 'reason', 'evidence'], properties: {
    assessment: { type: 'string', enum: ASSESSMENTS },
    answerCorrectness: { anyOf: [{ type: 'integer', minimum: 1, maximum: 5 }, { type: 'null' }] },
    materialFaithfulness: { type: 'integer', minimum: 1, maximum: 5 },
    scopeCompliance: { type: 'string', enum: ['compliant', 'violation', 'uncertain'] },
    reason: { type: 'string' },
    evidence: { type: 'array', items: { type: 'object', additionalProperties: false,
      required: ['sourceId', 'quote', 'relevance'], properties: { sourceId: { type: 'string' }, quote: { type: 'string' }, relevance: { type: 'string' } } } },
  } }
export const ANSWER_DISPOSITIONS = ['substantive-answer', 'abstention', 'cannot-grade']
export const JUDGE_SCHEMA_V2 = { ...JUDGE_SCHEMA,
  required: [...JUDGE_SCHEMA.required, 'answerDisposition'],
  properties: { ...JUDGE_SCHEMA.properties,
    answerDisposition: { type: 'string', enum: ANSWER_DISPOSITIONS },
    materialFaithfulness: { anyOf: [{ type: 'integer', minimum: 1, maximum: 5 }, { type: 'null' }] } } }
export const judgeOutputSchema = protocol => protocol.version === 2 ? JUDGE_SCHEMA_V2 : JUDGE_SCHEMA
const leaves = value => typeof value === 'string' ? [value] : Array.isArray(value) ? value.flatMap(leaves)
  : value && typeof value === 'object' ? Object.values(value).flatMap(leaves) : []
const exact = (value, keys) => value && typeof value === 'object' && !Array.isArray(value)
  && Object.keys(value).sort().join(',') === [...keys].sort().join(',')

/** An explicit new cohort may continue only untouched inputs from one closed
 * historical run. It cannot change its inputs/rubric/model or retry a failed
 * input; the old runtime and every raw receipt remain independently pinned. */
export function validateJudgeContinuationParent(parent, current) {
  const incomplete = parent?.schema === 'storyforge.narrative-reader-incomplete-judge-run'
  if ((incomplete ? parent.version !== 1 : parent?.schema !== 'storyforge.narrative-reader-judge-run' || ![1, 3].includes(parent.version))
    || parent.accepted !== false || parent.continuation || !parent.runtimeHashes || !Object.keys(parent.runtimeHashes).length) {
    throw Error('Continuation requires one frozen original judge run')
  }
  if (current.schema !== parent.schema) throw Error('Continuation changes full versus incomplete evidence boundary')
  if (incomplete && (parent.protocolVersion !== 2 || parent.readerCoverage?.completeMatrixAcceptance !== false
    || sha256(parent.readerCoverage) !== sha256(current.readerCoverage) || parent.eligibleObservations !== current.eligibleObservations)) {
    throw Error('Continuation changes frozen incomplete reader coverage')
  }
  if ((parent.protocolVersion ?? 1) !== (current.protocolVersion ?? 1)) throw Error('Continuation changes frozen protocol version')
  for (const key of ['entryId', 'provider', 'model', 'readerProvider', 'readerModel', 'reasoningEffort',
    'totalObservations', 'distinctPrompts', 'cases', 'dispatchOrder']) {
    if (sha256(parent[key]) !== sha256(current[key])) throw Error(`Continuation changes frozen ${key}`)
  }
  const sorted = value => Object.entries(value ?? {}).sort(([a], [b]) => a.localeCompare(b))
  if (sha256(sorted(parent.sourceHashes)) !== sha256(sorted(current.sourceHashes))) throw Error('Continuation changes frozen source evidence or rubric')
  return parent
}

export function validatePriorJudgeCall(prior, request, protocol) {
  if (!prior?.started || !prior.request || !prior.result) throw Error('Historical call has an unknown outcome; continuation is blocked')
  const { started, request: sent, result } = prior
  if (started.promptHash !== request.promptHash || sent.promptHash !== request.promptHash
    || sha256(sent.messages) !== request.promptHash || sent.model !== protocol.model
    || sha256(sent.outputSchema) !== sha256(judgeOutputSchema(protocol)) || result.promptHash !== request.promptHash
    || result.model !== protocol.model || result.provider !== protocol.provider || typeof result.dispatched !== 'boolean'
    || !['completed', 'failed', 'unknown-or-interrupted', ...(protocol.version === 2 ? ['invalid-judgment'] : [])].includes(result.status)) throw Error('Historical judge call identity or status changed')
  if (result.status === 'invalid-judgment') {
    if (!result.dispatched || result.generationCompleted !== true || !judgeUsageWithinBudget(result.usage, protocol)) throw Error('Invalid judgment lacks terminal generation or budget evidence')
    let validationError
    try { validateJudgeAnswer(result.rawText, request, protocol) } catch (error) { validationError = String(error) }
    if (!validationError || validationError !== result.validationError || result.judgment !== undefined) throw Error('Historical invalid judgment classification changed')
    return { ...result }
  }
  if (result.status !== 'completed') return { ...result }
  if (!result.dispatched || !judgeUsageWithinBudget(result.usage, protocol)
    || (protocol.version === 2 && result.generationCompleted !== true)) throw Error('Historical successful judge call lacks dispatch, terminal generation or budget evidence')
  return { ...result, judgment: validateJudgeAnswer(result.rawText, request, protocol) }
}

export function judgeSummaryName(existing, callCount) {
  if (!Number.isSafeInteger(callCount) || callCount < 0) throw Error('Invalid judge call count')
  const names = new Set(existing), prefix = `summary-${String(callCount).padStart(4, '0')}`
  for (let sequence = 1; sequence < 10_000; sequence++) {
    const name = `${prefix}-invocation-${String(sequence).padStart(4, '0')}.json`
    if (!names.has(name)) return name
  }
  throw Error('Too many judge invocations for this call count')
}

export function validateJudgeProtocol(protocol) {
  const limits = ['maxInputBytes', 'maxEstimatedInputTokens', 'maxObservedInputTokens', 'maxObservedOutputTokens',
    'maxReasonCharacters', 'maxEvidence', 'maxQuoteCharacters', 'maxRelevanceCharacters', 'timeoutMs']
  if (protocol.schema !== 'storyforge.narrative-reader-judge-protocol' || ![1, 2].includes(protocol.version)
    || protocol.entryId !== JUDGE_ENTRY_ID || protocol.provider !== 'local-codex-subscription'
    || typeof protocol.model !== 'string' || !protocol.model || protocol.reasoningEffort !== 'medium'
    || protocol.retries !== 0 || protocol.accepted !== false || protocol.independentHumanReviews !== 0
    || !Number.isInteger(protocol.concurrency) || protocol.concurrency < 1 || protocol.concurrency > 2
    || !Number.isSafeInteger(protocol.pilotActualCalls) || protocol.pilotActualCalls < 1
    || typeof protocol.systemPrompt !== 'string' || !protocol.systemPrompt.trim()
    || limits.some(key => !Number.isSafeInteger(protocol.budget?.[key]) || protocol.budget[key] < 1)
    || protocol.budget.timeoutMs > 300000 || protocol.budget.serverEnforcedOutputTokenLimit !== null) {
    throw Error('Unknown or unbounded semantic judge protocol')
  }
  if (protocol.version === 2 && (protocol.rubricVersion !== 'content-disposition-grounding-scope-v2'
    || !exact(protocol.failurePolicy, ['invalidJudgment', 'transportFailure', 'missingOrExceededUsage', 'unknownOutcome'])
    || protocol.failurePolicy.invalidJudgment !== 'record-ungraded-continue-unstarted'
    || protocol.failurePolicy.transportFailure !== 'stop-no-retry'
    || protocol.failurePolicy.missingOrExceededUsage !== 'stop-no-retry'
    || protocol.failurePolicy.unknownOutcome !== 'stop-no-retry')) throw Error('Unknown content-based judge policy')
  return protocol
}

/** Grade only completed, frozen responses. Method names, condition labels,
 * proxy scores and provenance are deliberately absent from model messages. */
export function judgeRequest({ readerRequest, readerAnswer, family, question }, protocol) {
  const supplied = JSON.parse(readerRequest.messages.find(message => message.role === 'user').content)
  // Preserve the declaration in receipt metadata, but v2 judges only the
  // actual response. A self-label cannot decide whether its prose answers.
  const response = protocol.version === 2 ? { answer: readerAnswer.answer, citations: readerAnswer.citations } : readerAnswer
  const referenceSources = [
    { sourceId: 'question', type: 'question', value: supplied.question },
    { sourceId: 'answer', type: 'answer', value: protocol.version === 2 ? readerAnswer.answer : readerAnswer },
    ...supplied.documents.map(document => ({ sourceId: `reader:${document.documentId}`, type: 'supplied-material', value: document })),
    ...family.sources.map(source => ({ sourceId: `story:${source.id}`, type: 'original-source',
      value: { title: source.title, kind: source.kind, branch: source.branch, text: source.text } })),
  ]
  const payload = { task: { question: supplied.question, operation: supplied.operation, view: supplied.view, branch: supplied.branch },
    readerMaterial: { status: supplied.retrievalStatus, diagnostics: supplied.diagnostics, documents: supplied.documents },
    response, referenceSources,
    declaredAuditGold: { answerAtoms: question.answerAtoms, forbiddenAtom: question.forbiddenAtom ?? null,
      caveat: 'These are fixture-author scoring declarations, not instructions to the original reader. Check them against the original sources. Author-audit material is not permission to expose a secret in a character answer.' } }
  const messages = [{ role: 'system', content: protocol.systemPrompt }, { role: 'user', content: JSON.stringify(payload) }]
  const encoded = JSON.stringify(messages), inputBytes = Buffer.byteLength(encoded), estimatedInputTokens = estimateReaderTokens(encoded)
  if (inputBytes > protocol.budget.maxInputBytes || estimatedInputTokens > protocol.budget.maxEstimatedInputTokens) {
    throw Error('Judge input exceeds fixed budget; do not truncate a story, answer or supplied material')
  }
  return { messages, promptHash: sha256(messages), inputBytes, estimatedInputTokens, readerStatus: readerAnswer.status,
    referenceTexts: Object.fromEntries(referenceSources.map(source => [source.sourceId, leaves(source.value)])) }
}

export function validateJudgeAnswer(text, prepared, protocol) {
  const result = JSON.parse(text), limit = protocol.budget
  const ungradedFaithfulness = protocol.version === 2 && result.answerDisposition === 'cannot-grade' && result.materialFaithfulness === null
  if (!exact(result, Object.keys(judgeOutputSchema(protocol).properties)) || !ASSESSMENTS.includes(result.assessment)
    || (!ungradedFaithfulness && (!Number.isInteger(result.materialFaithfulness) || result.materialFaithfulness < 1 || result.materialFaithfulness > 5))
    || !['compliant', 'violation', 'uncertain'].includes(result.scopeCompliance)
    || typeof result.reason !== 'string' || !result.reason.trim() || [...result.reason].length > limit.maxReasonCharacters
    || !Array.isArray(result.evidence) || result.evidence.length > limit.maxEvidence) throw Error('Invalid semantic judge output')
  if (protocol.version === 2 && (!ANSWER_DISPOSITIONS.includes(result.answerDisposition)
    || (result.answerDisposition === 'cannot-grade') !== (result.assessment === 'cannot-grade')
    || (result.answerDisposition === 'abstention') !== result.assessment.endsWith('abstention'))) throw Error('Judge assessment conflicts with content disposition')
  const answered = protocol.version === 2 ? result.answerDisposition === 'substantive-answer' : prepared.readerStatus === 'answered'
  if (result.assessment === 'cannot-grade' || !answered) {
    if (result.answerCorrectness !== null) throw Error('Abstentions and ungradable answers must not receive an answer-correctness score')
  } else if (!Number.isInteger(result.answerCorrectness) || result.answerCorrectness < 1 || result.answerCorrectness > 5) {
    throw Error('Answered cases require a 1–5 correctness score')
  }
  if (answered && result.assessment.endsWith('abstention') || !answered && ['correct', 'partly-correct', 'incorrect'].includes(result.assessment)) {
    throw Error('Judge disposition disagrees with the declared v1 status or v2 content classification')
  }
  if (result.assessment !== 'cannot-grade' && !result.evidence.length) throw Error('Judge conclusions require traceable evidence')
  if (protocol.version === 2 && result.assessment !== 'cannot-grade' && !result.evidence.some(item => item?.sourceId === 'answer')) {
    throw Error('Content disposition requires an exact quote from the answer prose')
  }
  for (const item of result.evidence) {
    if (!exact(item, ['sourceId', 'quote', 'relevance']) || typeof item.sourceId !== 'string'
      || typeof item.quote !== 'string' || !item.quote.length || [...item.quote].length > limit.maxQuoteCharacters
      || typeof item.relevance !== 'string' || !item.relevance.trim() || [...item.relevance].length > limit.maxRelevanceCharacters
      || !prepared.referenceTexts[item.sourceId]?.some(source => source.includes(item.quote))) {
      throw Error('Judge quotation does not match its named frozen source')
    }
  }
  return result
}

export function judgeUsageWithinBudget(usage, protocol) {
  return !!usage && Number.isSafeInteger(usage.inputTokens) && usage.inputTokens >= 0
    && Number.isSafeInteger(usage.outputTokens) && usage.outputTokens >= 0
    && usage.inputTokens <= protocol.budget.maxObservedInputTokens && usage.outputTokens <= protocol.budget.maxObservedOutputTokens
}

/** A terminal attempt is not necessarily a model dispatch or valid judgment. */
export function judgeExecutionCounts(calls, distinctPrompts) {
  const dispatched = calls.filter(call => call.dispatched === true)
  return { attemptedPrompts: calls.length, dispatchedActualCalls: dispatched.length,
    completedActualCalls: dispatched.filter(call => call.status === 'completed').length,
    invalidJudgmentActualCalls: dispatched.filter(call => call.status === 'invalid-judgment').length,
    failedActualCalls: dispatched.filter(call => !['completed', 'invalid-judgment'].includes(call.status)).length,
    preDispatchFailures: calls.filter(call => call.dispatched !== true).length,
    notYetAttempted: distinctPrompts - calls.length, notYetCalled: distinctPrompts - dispatched.length,
    executionComplete: calls.length === distinctPrompts && calls.every(call => call.dispatched === true
      && ['completed', 'invalid-judgment'].includes(call.status)) }
}

/** Deterministic pilot ordering covers every operation first, then uses all
 * remaining cases. It depends on input identity, never a score or verdict. */
export function orderJudgeRequests(prepared) {
  const ranked = [...prepared].sort((a, b) => a.request.promptHash.localeCompare(b.request.promptHash))
  const unique = new Map()
  const operations = [...new Set(ranked.map(item => item.operation))].sort()
  for (const operation of operations) {
    const first = ranked.find(item => item.operation === operation)
    unique.set(first.request.promptHash, first.request)
  }
  for (const { request } of ranked) unique.set(request.promptHash, request)
  return unique
}

export function summarizeJudge(rows) {
  const median = values => { const ordered = [...values].sort((a, b) => a - b); return ordered.length
    ? (ordered[Math.floor((ordered.length - 1) / 2)] + ordered[Math.ceil((ordered.length - 1) / 2)]) / 2 : null }
  const group = selected => ({ observations: selected.length,
    distinctGradedPrompts: new Set(selected.map(row => row.judgePromptHash)).size,
    assessments: Object.fromEntries(ASSESSMENTS.map(label => [label, selected.filter(row => row.judgment.assessment === label).length])),
    answeredAndGradable: selected.filter(row => row.judgment.answerCorrectness !== null).length,
    answerCorrectnessMedian: median(selected.flatMap(row => row.judgment.answerCorrectness === null ? [] : [row.judgment.answerCorrectness])),
    faithfulnessMedian: median(selected.flatMap(row => row.judgment.materialFaithfulness === null ? [] : [row.judgment.materialFaithfulness])),
    scopeViolations: selected.filter(row => row.judgment.scopeCompliance === 'violation').length,
    scopeUncertain: selected.filter(row => row.judgment.scopeCompliance === 'uncertain').length,
    ...(selected.some(row => row.judgment.answerDisposition) ? {
      contentDispositions: Object.fromEntries(ANSWER_DISPOSITIONS.map(value => [value, selected.filter(row => row.judgment.answerDisposition === value).length])),
      declaredStatusMatrix: Object.fromEntries(['answered', 'insufficient', 'unsupported'].map(status => [status,
        Object.fromEntries(ANSWER_DISPOSITIONS.map(value => [value, selected.filter(row => row.readerReportedStatus === status && row.judgment.answerDisposition === value).length]))])),
      statusComparable: selected.filter(row => row.judgment.answerDisposition !== 'cannot-grade' && row.readerReportedStatus).length,
      statusDisagreements: selected.filter(row => row.judgment.answerDisposition !== 'cannot-grade' && row.readerReportedStatus
        && (row.readerReportedStatus === 'answered') !== (row.judgment.answerDisposition === 'substantive-answer')).length,
      faithfulnessScored: selected.filter(row => row.judgment.materialFaithfulness !== null).length,
    } : {}) })
  const by = field => Object.fromEntries([...new Set(rows.map(row => row[field]))].sort().map(key => [key, group(rows.filter(row => row[field] === key))]))
  return { byCondition: by('condition'), byOperation: by('operation'), bySplit: by('split'),
    boundary: 'One distinct provider+model judgment per frozen prompt, not a human verdict. Shared responses are paired observations, not independent samples. Abstentions are scored separately from answer correctness. No acceptance threshold is inferred from these medians.' }
}

import { test } from 'node:test'
import assert from 'node:assert/strict'
import { readFileSync } from 'node:fs'
import { judgeRequest, validateJudgeProtocol, validateJudgeAnswer, judgeUsageWithinBudget,
  orderJudgeRequests, summarizeJudge, validateJudgeContinuationParent, validatePriorJudgeCall, judgeSummaryName, JUDGE_SCHEMA } from './narrative-reader-judge-contract.mjs'

const protocol = JSON.parse(readFileSync(new URL('../tests/acceptance/narrative-world/reader-judge-protocol-20261015-v1.json', import.meta.url)))
const input = () => ({ readerRequest: { model: 'POISON-MODEL', condition: 'POISON-CONDITION',
  messages: [{ role: 'user', content: JSON.stringify({ question: '铜铃在哪里？', operation: 'original-read', view: 'author', branch: 'canon',
    retrievalStatus: 'matched', diagnostics: [], documents: [{ documentId: 'D1', title: '第一幕', text: '铜铃在阿澈掌心。', atom: null, evidence: [] }] }) }] },
  readerAnswer: { status: 'answered', answer: '铜铃在阿澈手中。', citations: [{ documentId: 'D1', quote: '铜铃在阿澈掌心。' }] },
  family: { sources: [{ id: 'story-a', title: '第一幕', kind: 'chapter', branch: 'canon', text: '铜铃在阿澈掌心。小桥并不知道。' }],
    score: 'POISON-SCORE', condition: 'POISON-CONDITION' }, question: { answerAtoms: ['铜铃在阿澈手中'], forbiddenAtom: null } })
const judgment = () => ({ assessment: 'correct', answerCorrectness: 5, materialFaithfulness: 5, scopeCompliance: 'compliant',
  reason: '掌心与手中是忠实改写。', evidence: [{ sourceId: 'reader:D1', quote: '铜铃在阿澈掌心。', relevance: '读者材料支持回答。' }] })

test('independent judge messages are blinded while retaining actual materials and explicit audit evidence', () => {
  const value = judgeRequest(input(), protocol), text = JSON.stringify(value.messages)
  assert.doesNotMatch(text, /POISON/)
  assert.match(text, /小桥并不知道/)
  assert.match(text, /declaredAuditGold/)
  assert.equal(validateJudgeAnswer(JSON.stringify(judgment()), value, protocol).answerCorrectness, 5)
})
test('quotes are bound to their named source; matching another source or inventing a sentence fails', () => {
  const value = judgeRequest(input(), protocol)
  for (const evidence of [
    { sourceId: 'reader:D1', quote: '小桥并不知道。', relevance: 'wrong source' },
    { sourceId: 'story:story-a', quote: '铜铃已在河底。', relevance: 'invented' },
    { sourceId: 'missing', quote: '铜铃在阿澈掌心。', relevance: 'unknown identity' },
  ]) assert.throws(() => validateJudgeAnswer(JSON.stringify({ ...judgment(), evidence: [evidence] }), value, protocol), /quotation/)
})
test('abstentions do not inflate correctness; actual response status constrains dispositions', () => {
  const data = input(); data.readerAnswer = { status: 'insufficient', answer: '无法判断。', citations: [] }
  const value = judgeRequest(data, protocol)
  const answer = { ...judgment(), assessment: 'unjustified-abstention', answerCorrectness: null }
  assert.equal(validateJudgeAnswer(JSON.stringify(answer), value, protocol).answerCorrectness, null)
  assert.throws(() => validateJudgeAnswer(JSON.stringify({ ...answer, answerCorrectness: 5 }), value, protocol), /Abstentions/)
  assert.throws(() => validateJudgeAnswer(JSON.stringify({ ...answer, assessment: 'correct' }), value, protocol), /disposition/)
  assert.throws(() => validateJudgeAnswer(JSON.stringify(answer), judgeRequest(input(), protocol), protocol), /correctness score|disposition/)
})
test('uncertainty remains representable and cannot be given a manufactured answer score', () => {
  const value = judgeRequest(input(), protocol), answer = { ...judgment(), assessment: 'cannot-grade', answerCorrectness: null, evidence: [] }
  assert.equal(validateJudgeAnswer(JSON.stringify(answer), value, protocol).assessment, 'cannot-grade')
  assert.throws(() => validateJudgeAnswer(JSON.stringify({ ...answer, answerCorrectness: 3 }), value, protocol), /ungradable/)
})
test('fixed input budget refuses a whole oversized case without modifying or clipping it', () => {
  const data = input(), before = JSON.stringify(data)
  assert.throws(() => judgeRequest(data, { ...protocol, budget: { ...protocol.budget, maxInputBytes: 30 } }), /fixed budget/)
  assert.equal(JSON.stringify(data), before)
})
test('unknown output fields, unsupported scores, missing proof and long reasons are rejected', () => {
  const value = judgeRequest(input(), protocol)
  for (const changes of [{ adopted: true }, { materialFaithfulness: 6 }, { assessment: 'passed' },
    { evidence: [] }, { reason: 'x'.repeat(protocol.budget.maxReasonCharacters + 1) }]) {
    assert.throws(() => validateJudgeAnswer(JSON.stringify({ ...judgment(), ...changes }), value, protocol))
  }
})
test('protocol bounds and observed usage are explicit, finite and nonnegative', () => {
  assert.equal(validateJudgeProtocol(protocol), protocol)
  for (const budget of [{ ...protocol.budget, timeoutMs: 900000 }, { ...protocol.budget, maxInputBytes: Infinity },
    { ...protocol.budget, maxEvidence: undefined }]) assert.throws(() => validateJudgeProtocol({ ...protocol, budget }), /unbounded/)
  assert.equal(judgeUsageWithinBudget({ inputTokens: 20, outputTokens: 30 }, protocol), true)
  for (const usage of [null, { inputTokens: -1, outputTokens: 1 }, { inputTokens: 20, outputTokens: 6001 }]) {
    assert.equal(judgeUsageWithinBudget(usage, protocol), false)
  }
})
test('pilot ordering covers operations before remaining cases and never uses scores', () => {
  const values = [{ operation: 'b', request: { promptHash: 'a' } }, { operation: 'b', request: { promptHash: 'b' } },
    { operation: 'a', request: { promptHash: 'c' } }, { operation: 'a', request: { promptHash: 'c' } }]
  assert.deepEqual([...orderJudgeRequests(values).keys()], ['c', 'a', 'b'])
  assert.deepEqual([...orderJudgeRequests(values.reverse().map(row => ({ ...row, score: -100 }))).keys()], ['c', 'a', 'b'])
})
test('aggregation preserves repeated observations and abstention denominators without treating them as independent calls', () => {
  const row = { condition: 'method', operation: 'read', split: 'holdout', judgePromptHash: 'one', judgment: judgment() }
  const refused = { ...row, judgePromptHash: 'two', judgment: { ...judgment(), assessment: 'justified-abstention', answerCorrectness: null } }
  const result = summarizeJudge([row, { ...row }, refused]).byCondition.method
  assert.equal(result.observations, 3); assert.equal(result.distinctGradedPrompts, 2)
  assert.equal(result.answeredAndGradable, 2); assert.equal(result.answerCorrectnessMedian, 5)
  assert.equal(result.assessments['justified-abstention'], 1)
})

const parentManifest = () => ({ schema: 'storyforge.narrative-reader-judge-run', version: 1, accepted: false,
  entryId: 'eval.narrative-world.reader-semantic-review', provider: protocol.provider, model: protocol.model,
  readerProvider: protocol.provider, readerModel: 'reader-model', reasoningEffort: protocol.reasoningEffort,
  sourceHashes: { rubric: 'one', story: 'two' }, runtimeHashes: { driver: 'old-code' },
  totalObservations: 2, distinctPrompts: 1, cases: [{ id: 'one' }, { id: 'two' }], dispatchOrder: ['prompt'] })
test('explicit continuation retains original evidence/model/order but records a new runtime separately', () => {
  const parent = parentManifest(), current = { ...structuredClone(parent), runtimeHashes: { driver: 'new-code' } }
  assert.equal(validateJudgeContinuationParent(parent, current), parent)
  for (const change of [{ model: 'other' }, { sourceHashes: { rubric: 'changed', story: 'two' } },
    { cases: [{ id: 'two' }, { id: 'one' }] }, { dispatchOrder: ['another'] }]) {
    assert.throws(() => validateJudgeContinuationParent(parent, { ...current, ...change }), /Continuation changes/)
  }
  assert.throws(() => validateJudgeContinuationParent({ ...parent, version: 2 }, current), /original judge run/)
})
const priorCall = () => {
  const request = judgeRequest(input(), protocol)
  return { request, prior: { started: { promptHash: request.promptHash },
    request: { promptHash: request.promptHash, model: protocol.model, messages: request.messages, outputSchema: JUDGE_SCHEMA },
    result: { promptHash: request.promptHash, model: protocol.model, provider: protocol.provider, dispatched: true,
      status: 'completed', rawText: JSON.stringify(judgment()), usage: { inputTokens: 50, outputTokens: 50 } } } }
}
test('prior successes are revalidated and prior failures stay failures without fabricated judgments', () => {
  const { request, prior } = priorCall()
  assert.equal(validatePriorJudgeCall(prior, request, protocol).judgment.assessment, 'correct')
  for (const status of ['failed', 'unknown-or-interrupted']) {
    const failed = { ...prior, result: { ...prior.result, status, usage: null, rawText: '' } }
    const value = validatePriorJudgeCall(failed, request, protocol)
    assert.equal(value.status, status); assert.equal(value.judgment, undefined)
  }
})
test('missing terminal receipts, altered prompts, model substitutions and invalid successful usage block continuation', () => {
  const { request, prior } = priorCall()
  for (const bad of [{ ...prior, result: undefined }, { ...prior, started: undefined },
    { ...prior, request: { ...prior.request, messages: [] } },
    { ...prior, result: { ...prior.result, model: 'other' } },
    { ...prior, result: { ...prior.result, dispatched: false } },
    { ...prior, result: { ...prior.result, usage: null } }]) {
    assert.throws(() => validatePriorJudgeCall(bad, request, protocol))
  }
})
test('a zero-dispatch failure after dry-run has its own summary and cannot mask or overwrite earlier evidence', () => {
  const names = ['summary-0021.json'], before = [...names]
  assert.equal(judgeSummaryName(names, 21), 'summary-0021-invocation-0001.json')
  assert.deepEqual(names, before)
  assert.equal(judgeSummaryName([...names, 'summary-0021-invocation-0001.json'], 21), 'summary-0021-invocation-0002.json')
  assert.throws(() => judgeSummaryName(names, -1), /Invalid/)
})

