function buildFailureCode(value: string | undefined): string | null {
  if (!value) return null
  try {
    const parsed = JSON.parse(value) as { code?: unknown }
    return typeof parsed.code === 'string' ? parsed.code : null
  } catch { return null }
}

function budgetLedgerHasOutstandingReservations(value: string | undefined): boolean {
  if (!value || value === '{}') return false
  try {
    const parsed = JSON.parse(value) as { version?: unknown; attempts?: unknown }
    if (parsed.version !== 2 || !Array.isArray(parsed.attempts)) return true
    return parsed.attempts.some(attempt => {
      if (!attempt || typeof attempt !== 'object' || Array.isArray(attempt)) return true
      const row = attempt as Record<string, unknown>
      return row.usageKnown === false && row.usage != null
    })
  } catch { return true }
}

function compatibilityReport(value: string | undefined): ProductBuildCompatibilityReportV1 | null {
  if (!value) return null
  try {
    const parsed = JSON.parse(value) as Partial<ProductBuildCompatibilityReportV1>
    return parsed.schema === 'storyforge.product-build-compatibility' && parsed.version === 1
      && ['compatible', 'restart-recommended', 'breaking'].includes(parsed.level ?? '')
      ? parsed as ProductBuildCompatibilityReportV1 : null
  } catch { return null }
}

export function shouldAutoContinueProductProductionV1(input: {
  productionStatus: string | null
  buildStatus: string | null
  running: boolean
}): boolean {
  return !input.running && input.productionStatus === 'producing'
    && input.buildStatus != null && ['authorized', 'building'].includes(input.buildStatus)
}

export function productProductionRecoveryCheckDelayV1(
  progress: ProductProductionProgressV1,
  now = Date.now(),
): number | null {
  const recoveryTimes = progress.tasks.flatMap(task => (
    task.status === 'running' && task.recoveryCheckAt != null ? [task.recoveryCheckAt] : []
  ))
  if (progress.buildStatus !== 'building' || recoveryTimes.length === 0) return null
  return Math.max(250, Math.min(...recoveryTimes) - now + 50)
}

