    if (result === 'resumed') setUnknownResultDisposition('')
    await refresh(details.production.id)
    setMessage(result === 'resumed'
      ? 'Build 已恢复；暂停时仍在途的请求已先按 Run、attempt 与 epoch 封账。'
      : 'Build 已暂停并递增 control epoch；如有仍在途的供应商请求，恢复前会要求明确结算。')
