    .replace(
      /(?:纸页|纸面|日志|手稿|档案)(?:上|中)?[^，。；\n]{0,20}(?:写着|写有|写满|记录着|标注着)[^，。；\n]*/gu,
      '纸面仅以无字的抽象线条表现研究轨迹',
