export async function hashStateJson(stateJson: string): Promise<string> {
  const data = new TextEncoder().encode(stateJson);
  const digestPromise = crypto.subtle.digest("SHA-256", data);
  const digest = Dexie.currentTransaction
    ? await Dexie.waitFor(digestPromise)
    : await digestPromise;
  return Array.from(new Uint8Array(digest), (byte) =>
    byte.toString(16).padStart(2, "0"),
  ).join("");
}

const PRODUCT_RUNTIME_CHECKPOINT_SUBJECT_PURPOSES_V1 = new Set<ProductRuntimeCheckpointPurposeV1>([
  "combat-retry",
  "milestone",
]);

/**
 * Normalizes the only legacy checkpoint shape: a missing purpose is `manual`.
 * Product-specific callers still own validation of what an encounter or
 * milestone key refers to; this shared boundary owns the purpose/key pairing.
 */
export function normalizeProductRuntimeCheckpointPurposeV1(input: {
  purpose?: unknown;
  subjectKey?: unknown;
}): {
  purpose: ProductRuntimeCheckpointPurposeV1;
  subjectKey: string | null;
} {
  const rawPurpose = input.purpose;
  const purpose = rawPurpose === undefined
    ? "manual"
    : typeof rawPurpose === "string"
      && PRODUCT_RUNTIME_CHECKPOINT_PURPOSES_V1.includes(
        rawPurpose as ProductRuntimeCheckpointPurposeV1,
      )
      ? rawPurpose as ProductRuntimeCheckpointPurposeV1
      : null;
  if (!purpose) throw new Error("检查点用途无效。");

  const rawSubjectKey = input.subjectKey;
  const subjectKey = rawSubjectKey == null
    ? null
    : typeof rawSubjectKey === "string"
      ? rawSubjectKey.trim() || null
      : null;
  if (rawSubjectKey != null && typeof rawSubjectKey !== "string") {
    throw new Error("检查点对象必须是字符串。");
  }
  if (subjectKey && subjectKey.length > 200) {
    throw new Error("检查点对象不能超过 200 个字符。");
  }

  const requiresSubject = PRODUCT_RUNTIME_CHECKPOINT_SUBJECT_PURPOSES_V1.has(purpose);
  if (requiresSubject && !subjectKey) {
    throw new Error(`${purpose} 检查点必须绑定有效对象。`);
  }
  if (!requiresSubject && subjectKey != null) {
    throw new Error(`${purpose} 检查点不能绑定对象。`);
  }
  return { purpose, subjectKey };
}

export type NormalizedProductRuntimeCheckpointV1 = ProductRuntimeCheckpoint & {
  worldGroupId: number | null;
  purpose: ProductRuntimeCheckpointPurposeV1;
  subjectKey: string | null;
};

/** Strict persisted-row parser used by readers before trusting checkpoint data. */
export function parseProductRuntimeCheckpointV1(
  value: unknown,
): NormalizedProductRuntimeCheckpointV1 {
  if (!isObject(value)) throw new Error("检查点记录必须是对象。");
  const id = value.id === undefined
    ? undefined
    : assertFiniteInteger(value.id, "检查点 id", 1, Number.MAX_SAFE_INTEGER);
  const projectId = assertFiniteInteger(
    value.projectId,
    "检查点 projectId",
    1,
    Number.MAX_SAFE_INTEGER,
  );
  const worldGroupId = value.worldGroupId == null
    ? null
    : assertFiniteInteger(
      value.worldGroupId,
      "检查点 worldGroupId",
      1,
      Number.MAX_SAFE_INTEGER,
    );
  const sessionId = assertFiniteInteger(
    value.sessionId,
    "检查点 sessionId",
    1,
    Number.MAX_SAFE_INTEGER,
  );
  const throughSequence = assertFiniteInteger(
    value.throughSequence,
    "检查点序号",
    0,
    Number.MAX_SAFE_INTEGER,
  );
  if (typeof value.name !== "string" || !value.name.trim() || value.name !== value.name.trim()
    || value.name.length > 200) {
    throw new Error("检查点名称无效。");
  }
  const normalizedPurpose = normalizeProductRuntimeCheckpointPurposeV1({
    purpose: value.purpose,
    subjectKey: value.subjectKey,
  });
  if (value.subjectKey != null && value.subjectKey !== normalizedPurpose.subjectKey) {
    throw new Error("检查点对象不是规范字符串。");
  }
  if (typeof value.stateJson !== "string") throw new Error("检查点状态正文无效。");
  const state = parseProductRuntimeState(value.stateJson);
  if (state.lastSequence !== throughSequence) {
    throw new Error("检查点状态序号与 throughSequence 不一致。");
  }
  if (typeof value.stateHash !== "string" || !/^[a-f0-9]{64}$/.test(value.stateHash)) {
    throw new Error("检查点状态 Hash 无效。");
  }
  const createdAt = assertFiniteInteger(
    value.createdAt,
    "检查点创建时间",
    0,
    Number.MAX_SAFE_INTEGER,
  );
  return {
    ...(id == null ? {} : { id }),
    projectId,
    worldGroupId,
    sessionId,
    throughSequence,
    name: value.name,
    ...normalizedPurpose,
    stateJson: value.stateJson,
    stateHash: value.stateHash,
    createdAt,
  };
}

export async function createProductRuntimeCheckpoint(input: {
  sessionId: number;
  name: string;
  throughSequence?: number;
  purpose?: ProductRuntimeCheckpoint["purpose"];
  subjectKey?: string | null;
  /** Canonical source time for recovered derived checkpoints; defaults to creation time. */
  createdAt?: number;
}): Promise<ProductRuntimeCheckpoint> {
  if (!Number.isInteger(input.sessionId) || input.sessionId < 1) {
    throw new Error("检查点 sessionId 无效。");
  }
  if (typeof input.name !== "string") throw new Error("检查点名称无效。");
  const purpose = normalizeProductRuntimeCheckpointPurposeV1(input);
  return db.transaction(
    "rw",
    db.productRuntimeSessions,
    db.productRuntimeEvents,
    db.productRuntimeCheckpoints,
    async () => {
      const session = await db.productRuntimeSessions.get(input.sessionId);
      if (!session) throw new Error("产品运行会话不存在。");
      const events = await readSessionEvents(session);
      const latest = events.reduce(
        (max, event) => Math.max(max, event.sequence),
        0,
      );
      const throughSequence = input.throughSequence ?? latest;
      if (
        !Number.isInteger(throughSequence) ||
        throughSequence < 0 ||
        throughSequence > latest
      ) {
        throw new Error("检查点序号不在会话事件范围内。");
      }
      const state = replayProductRuntimeEvents(
        parseProductRuntimeState(session.initialStateJson),
        events,
        throughSequence,
      );
      if (state.lastSequence !== throughSequence) {
        throw new Error("检查点序号不是可重放的会话事件边界。");
      }
      const stateJson = JSON.stringify(state);
      const name = input.name.trim() || `检查点 ${throughSequence}`;
      if (name.length > 200) throw new Error("检查点名称不能超过 200 个字符。");
      const createdAt = input.createdAt ?? Date.now();
      if (!Number.isSafeInteger(createdAt) || createdAt < 0) {
        throw new Error("检查点创建时间无效。");
      }
      const checkpoint: ProductRuntimeCheckpoint = {
        projectId: session.projectId,
        worldGroupId: session.worldGroupId ?? null,
        sessionId: session.id!,
        throughSequence,
        name,
        ...purpose,
        stateJson,
        stateHash: await hashStateJson(stateJson),
        createdAt,
      };
      parseProductRuntimeCheckpointV1(checkpoint);
      checkpoint.id = (await db.productRuntimeCheckpoints.add(checkpoint)) as number;
      return checkpoint;
    },
  );
}

export async function verifyProductRuntimeCheckpoint(
  checkpointId: number,
): Promise<boolean> {
  try {
    const stored = await db.productRuntimeCheckpoints.get(checkpointId);
    if (!stored) return false;
    const checkpoint = parseProductRuntimeCheckpointV1(stored);
    const session = await db.productRuntimeSessions.get(checkpoint.sessionId);
    if (
      !session ||
      session.projectId !== checkpoint.projectId ||
      (session.worldGroupId ?? null) !== checkpoint.worldGroupId
    ) return false;
    const latestSequence = await readLatestSessionEventSequenceV1(checkpoint.sessionId);
    if (checkpoint.throughSequence > latestSequence) return false;
    if (await hashStateJson(checkpoint.stateJson) !== checkpoint.stateHash) return false;
    const replayed = await readProductRuntimeState(
      checkpoint.sessionId,
      checkpoint.throughSequence,
    );
    const stateJson = JSON.stringify(replayed);
    return (
      stateJson === checkpoint.stateJson &&
      (await hashStateJson(stateJson)) === checkpoint.stateHash
    );
  } catch {
    return false;
  }
}

export interface RecoveredProductRuntimeCheckpointV1 {
  checkpoint: ProductRuntimeCheckpoint;
  damagedCheckpointId: number;
  recoveryBaseCheckpointId: number | null;
}

export async function recoverProductRuntimeCheckpointFromEventsV1(
  checkpointId: number,
): Promise<RecoveredProductRuntimeCheckpointV1> {
  const damaged = await db.productRuntimeCheckpoints.get(checkpointId);
  if (!damaged) throw new Error("待恢复的产品运行检查点不存在。");
  if (await verifyProductRuntimeCheckpoint(checkpointId)) {
    throw new Error("产品运行检查点完整，无需恢复。");
  }
  const session = await db.productRuntimeSessions.get(damaged.sessionId);
  if (
    !session ||
    session.projectId !== damaged.projectId ||
    (session.worldGroupId ?? null) !== (damaged.worldGroupId ?? null)
  ) throw new Error("损坏检查点与产品运行会话作用域不一致。");

  const events = await readSessionEvents(session);
  const latestSequence = events[events.length - 1]?.sequence ?? 0;
  if (!Number.isInteger(damaged.throughSequence) || damaged.throughSequence < 0 || damaged.throughSequence > latestSequence) {
    throw new Error("损坏检查点序号超出可恢复事件范围。");
  }
  const recoveryName = `恢复 #${checkpointId} · ${damaged.name}`.slice(0, 200);
  const candidates = (await db.productRuntimeCheckpoints
    .where("sessionId").equals(session.id!).toArray())
    .filter(row => row.id !== checkpointId && row.throughSequence <= damaged.throughSequence)
    .sort((left, right) => right.throughSequence - left.throughSequence || right.createdAt - left.createdAt);
  const existing = candidates.find(row => row.throughSequence === damaged.throughSequence && row.name === recoveryName);
  if (existing?.id != null && await verifyProductRuntimeCheckpoint(existing.id)) {
    return { checkpoint: existing, damagedCheckpointId: checkpointId, recoveryBaseCheckpointId: null };
  }
  let recoveryBaseCheckpointId: number | null = null;
  for (const candidate of candidates) {
    if (candidate.throughSequence >= damaged.throughSequence || candidate.id == null) continue;
    if (await verifyProductRuntimeCheckpoint(candidate.id)) {
      recoveryBaseCheckpointId = candidate.id;
      break;
    }
  }
  const checkpoint = await createProductRuntimeCheckpoint({
    sessionId: session.id!, throughSequence: damaged.throughSequence, name: recoveryName,
  });
  if (!await verifyProductRuntimeCheckpoint(checkpoint.id!)) {
    throw new Error("事件重放生成的恢复检查点未通过完整性复验。");
  }
  return { checkpoint, damagedCheckpointId: checkpointId, recoveryBaseCheckpointId };
}

export interface BranchProductRuntimeSessionInputV1 {
  parentSessionId: number;
  throughSequence: number;
  title: string;
  seed?: string;
}

async function branchProductRuntimeSessionInternal(
  input: BranchProductRuntimeSessionInputV1,
): Promise<ProductRuntimeSession> {
  const parent = await db.productRuntimeSessions.get(input.parentSessionId);
  if (!parent) throw new Error("父产品运行会话不存在。");
  await verifyProductRuntimeSessionSourceV1({ scope: {
    projectId: parent.projectId, worldId: parent.worldId, workId: parent.workId,
  }, session: parent });
  const events = await readSessionEvents(parent);
  const latest = events.reduce(
    (max, event) => Math.max(max, event.sequence),
    0,
  );
  if (
    !Number.isInteger(input.throughSequence) ||
    input.throughSequence < 0 ||
    input.throughSequence > latest
  )
    throw new Error("分支序号不在父会话事件范围内。");
  const state = replayProductRuntimeEvents(
    parseProductRuntimeState(parent.initialStateJson),
    events,
    input.throughSequence,
  );
  rebaseProductRuntimeStateForBranchV1(state, input.throughSequence);
  state.lastSequence = 0;
  const childInput: CreateProductRuntimeSessionInput = {
    projectId: parent.projectId,
    worldGroupId: parent.worldGroupId ?? null,
    kind: parent.kind,
    title: input.title,
    seed: input.seed,
    canonSnapshot: parseJsonObject(parent.canonSnapshotJson, "Canon 冻结快照"),
    initialState: state,
  };
  let child: ProductRuntimeSession;
  if (parent.productReleaseId != null) {
    child = await createReleasedProductRuntimeSession({
      ...childInput,
      worldId: parent.worldId,
      workId: parent.workId,
      productReleaseId: parent.productReleaseId,
      origin: "branch",
    });
  } else {
    const parentBuild = await db.productBuilds.get(parent.productBuildId);
    if (!parentBuild) throw new Error("运行分支绑定的 Build Preview 不存在。");
    child = await createPreviewProductRuntimeSession({
      ...childInput,
      worldId: parent.worldId,
      workId: parent.workId,
      productBuildId: parent.productBuildId,
      expectedPreviewHash: parentBuild.previewHash,
      runtimeSourceHash: parent.runtimeSourceHash,
      origin: "branch",
    });
  }
  await db.productRuntimeSessions.update(child.id!, {
    parentSessionId: parent.id!,
    parentThroughSequence: input.throughSequence,
  });
  const boundChild = {
    ...child,
    parentSessionId: parent.id!,
    parentThroughSequence: input.throughSequence,
  };
  try {
    await cloneProductRuntimeBranchExtensionsV1({
      parent,
      child: boundChild,
      throughSequence: input.throughSequence,
      state,
      events,
    });
  } catch (cause) {
    throw new Error(
      `${parent.kind} 分支扩展复制失败:${cause instanceof Error ? cause.message : String(cause)}`,
    );
  }
  return boundChild;
}

export async function branchProductRuntimeSession(
  input: BranchProductRuntimeSessionInputV1,
): Promise<ProductRuntimeSession> {
  return branchProductRuntimeSessionInternal(input);
}

export async function deleteProductRuntimeSession(
  sessionId: number,
): Promise<void> {
  await db.transaction(
    "rw",
    transactionTablesForReferenceCascade("productRuntimeSessions"),
    async () => {
      // Preserve child ids before the registered parentSessionId setNull runs;
      // parentThroughSequence is the companion provenance field and must be
      // cleared in the same lifecycle operation.
      const children = await db.productRuntimeSessions
        .where("parentSessionId")
        .equals(sessionId)
        .toArray();
      // PROJECT_TABLES is authoritative for runtime-owned extensions such as the
      // unified Harness ledger. Cascading the registered references keeps this
      // lifecycle complete without a second hand-written run/event table list.
      await cascadeRegisteredReferences("productRuntimeSessions", sessionId);
      await db.productRuntimeEvents.where("sessionId").equals(sessionId).delete();
      await db.productRuntimeCheckpoints
        .where("sessionId")
        .equals(sessionId)
        .delete();
      for (const child of children) {
        if (child.id != null) {
          await db.productRuntimeSessions.update(child.id, {
            parentSessionId: null,
            parentThroughSequence: null,
          });
        }
      }
      await db.productRuntimeSessions.delete(sessionId);
    },
  );
}

