export type AssembleContextSourceStatus = 'included' | 'omitted' | 'trimmed'
export type AssembleContextSourceDelivery = 'full' | 'compressed' | 'truncated' | 'none'

/** A registered source could not honor the caller's explicit input budget. */
export class ContextSourceBudgetErrorV1 extends Error {
  constructor(
    message: string,
    readonly sourceKey: string,
    readonly requiredTokens: number,
    readonly budgetTokens: number,
  ) {
    super(message)
    this.name = 'ContextSourceBudgetErrorV1'
  }
}

/** An atomic source cannot be trimmed without changing the task contract. */
export class AtomicContextSourceBudgetErrorV1 extends ContextSourceBudgetErrorV1 {
  constructor(sourceKey: string, originalTokens: number, budgetTokens: number) {
    super(
      `[assembleContext] 原子来源 ${sourceKey} 超出预算:${originalTokens}>${budgetTokens}`,
      sourceKey,
      originalTokens,
      budgetTokens,
    )
    this.name = 'AtomicContextSourceBudgetErrorV1'
  }
}

/**
 * Per-source delivery evidence derived by assembleContext(). It records only
 * counts, hashes and delivery state; source text remains in segments/business tables.
 */
export interface AssembleContextSourceEvidence {
  key: string
  status: AssembleContextSourceStatus
  delivery: AssembleContextSourceDelivery
  /** SHA-256 of the registered reader's complete raw output before compression or truncation. */
  sourceHash?: string
  /** UTF-16 character count returned by the registered reader before its source budget was applied. */
  originalCharacters?: number
  /** UTF-16 character count actually delivered to the model. Zero for omitted/trimmed sources. */
  inputCharacters?: number
  /** Tokens returned by the registered reader before its source budget was applied. */
  originalTokens: number
  /** Tokens actually delivered to the model. Zero for omitted/trimmed sources. */
  inputTokens: number
  /** Semantic-compression evidence or deterministic-truncation fallback proof. */
  compression?: ContextCompressionEvidenceV1
}

export interface AssembleContextResult {
  text: string
  segments: ContextSegment[]
  included: string[]
  omitted: string[]
  trimmed: string[]
  /** Optional for historical/test fixtures; production assembleContext always supplies it. */
  sourceEvidence?: AssembleContextSourceEvidence[]
  /**
   * Transient exact bytes for sources whose model delivery was compressed or
   * truncated. Durable Harness callers persist these as source-snapshot Run
   * Artifacts before the provider boundary; ordinary callers may ignore them.
   * They are never spliced into the rendered prompt a second time.
   */
  sourceSnapshots?: Array<{ key: string; content: string }>
  totalInputTokens: number
  inputBudget: number
  overBudgetBeforeTrim: boolean
  overBudgetAfterTrim: boolean
}

