import { chunkDocument } from '../import/chunker'
import { db } from '../db/schema'
import { generateWorkspaceUid } from '../memory/identity'
import { generateWorkspaceScopeCode, generateWorldCode } from './identity'
import type {
  Chapter,
  CreateWorkspaceInput,
  NovelWorkflowProfile,
  OutlineNode,
  Project,
  Work,
  WorkKind,
  WorkspacePurpose,
  WorkspaceScope,
  World,
  CommunityWorldOrigin,
} from '../types'
import { scopeTransactionTables, stampNewRecord } from './scope'
import { buildWorkRecord } from './works'
import { deriveShortNovelStructure } from './work-kind'
import { buildShortNovelProductionRecordV1 } from '../short-novel/service'
import { countWords, plainTextToHtml } from '../utils/html'

export interface CreateWorkspaceOptions {
  /** ARCH-01: defaults to an independent authored work. */
  purpose?: WorkspacePurpose
  kind?: WorkKind
  novelProfile?: NovelWorkflowProfile | null
  preferredChapterCount?: number
  /** Optional author-written seed for the first short-novel chapter card. */
  initialChapterSummary?: string
  /** Optional author-provided prose imported into the first short-novel chapter. */
  initialChapterContent?: string
  /** Author import into an independent long novel; preserved as ordered source chapters. */
  importedNovelText?: string
  /** World identity options belong to the World root, never the Project shell root. */
  world?: {
    code?: string
    currentVersion?: number
    communityOrigin?: CommunityWorldOrigin
  }
}

export interface CreatedWorkspace {
  project: Project
  world: World
  work: Work
  scope: WorkspaceScope
}

function projectRoot(input: CreateWorkspaceInput, options: CreateWorkspaceOptions, now: number): Project {
  const allowedInputKeys = new Set([
    'workspaceUid', 'workspacePurpose', 'name', 'genres', 'customGenre', 'status',
    'description', 'targetWordCount', 'coverImage', 'writingStyleId', 'methodologyId',
    'enableMultiWorld', 'includeCultivationProgressInAI', 'activeCharacterDrivenPlanId',
    'productPlatformOptIns',
  ])
  const unknownKeys = Object.keys(input).filter(key => !allowedInputKeys.has(key))
  if (unknownKeys.length) {
    throw new Error(`创建工作区包含非当前字段：${unknownKeys.join('、')}`)
  }
  if (!Array.isArray(input.genres) || input.genres.some(genre => typeof genre !== 'string')) {
    throw new Error('创建工作区 genres 必须是字符串数组')
  }
  const purpose = options.purpose ?? input.workspacePurpose ?? 'independent-work'
  return {
    workspaceUid: input.workspaceUid ?? generateWorkspaceUid(),
    workspacePurpose: purpose,
    name: input.name,
    enableMultiWorld: input.enableMultiWorld,
    activeWorldId: null,
    activeWorkId: null,
    productPlatformOptIns: input.productPlatformOptIns,
    createdAt: now,
    updatedAt: now,
  }
}

async function createShortNovelSkeleton(
  scope: WorkspaceScope,
  targetWordCount: number,
  preferredChapterCount: number | undefined,
  initialChapterSummary: string | undefined,
  initialChapterContent: string | undefined,
  now: number,
): Promise<void> {
  const structure = deriveShortNovelStructure(targetWordCount, preferredChapterCount)
  const volume: OutlineNode = stampNewRecord(scope, 'outlineNodes', {
    projectId: scope.projectId,
    parentId: null,
    type: 'volume',
    title: '短篇正文',
    summary: '',
    order: 0,
    createdAt: now,
    updatedAt: now,
  }, { owner: 'work' })
  const volumeId = await db.outlineNodes.add(volume) as number

  for (let index = 0; index < structure.chapterCount; index += 1) {
    const title = `第${index + 1}章`
    const outline: OutlineNode = stampNewRecord(scope, 'outlineNodes', {
      projectId: scope.projectId,
      parentId: volumeId,
      type: 'chapter',
      title,
      summary: index === 0 ? initialChapterSummary?.trim() ?? '' : '',
      order: index,
      createdAt: now,
      updatedAt: now,
    }, { owner: 'work' })
    const outlineNodeId = await db.outlineNodes.add(outline) as number
    const chapter: Chapter = stampNewRecord(scope, 'chapters', {
      projectId: scope.projectId,
      outlineNodeId,
      title,
      content: index === 0 && initialChapterContent ? plainTextToHtml(initialChapterContent) : '',
      wordCount: index === 0 && initialChapterContent ? countWords(initialChapterContent) : 0,
      status: index === 0 && initialChapterContent ? 'draft' : 'outline',
      order: index,
      notes: '',
      createdAt: now,
      updatedAt: now,
    }, { owner: 'work' })
    await db.chapters.add(chapter)
  }
}

export function workspaceCreationTransactionTablesV1() {
  return scopeTransactionTables(db.outlineNodes, db.chapters, db.shortNovelProductions)
}

/**
 * Creates a new LocalWorkspace and its initial World/Work roots atomically.
 */
export async function createWorkspace(
  input: CreateWorkspaceInput,
  options: CreateWorkspaceOptions = {},
): Promise<CreatedWorkspace> {
  const initialChapterSummary = options.initialChapterSummary?.trim()
  const initialChapterContent = options.initialChapterContent?.trim()
  if ((initialChapterSummary || initialChapterContent) && (options.kind !== 'novel' || options.novelProfile !== 'short')) throw new Error('首章创意种子或导入正文只适用于短篇小说工作区')
  if (initialChapterSummary && initialChapterSummary.length > 4_000) throw new Error('首章创意种子不得超过 4000 字符')
  if (initialChapterContent && (initialChapterContent.length > 200_000 || countWords(initialChapterContent) > 25_000)) throw new Error('导入正文不得超过 20 万字符或 25,000 字')
  const importedNovelText = options.importedNovelText
  if (importedNovelText != null && (options.kind !== 'novel' || options.novelProfile !== 'long' || !importedNovelText.trim() || importedNovelText.length > 5_000_000)) throw new Error('导入原作需为非空长篇文本，最多 500 万字符')
  const now = Date.now()
  const preparedProject = projectRoot(input, options, now)
  const genres = input.genres.length ? [...input.genres] : ['other']
  return db.transaction('rw', workspaceCreationTransactionTablesV1(), async () => {
    const projectId = await db.projects.add(preparedProject) as number
    const world: World = {
      projectId,
      identityKind: preparedProject.workspacePurpose === 'world-engine' ? 'world-draft' : 'workspace-scope',
      code: preparedProject.workspacePurpose === 'world-engine'
        ? options.world?.code ?? generateWorldCode()
        : generateWorkspaceScopeCode(now),
      name: preparedProject.name,
      description: input.description,
      currentVersion: preparedProject.workspacePurpose === 'world-engine'
        ? options.world?.currentVersion ?? 0
        : 0,
      communityOrigin: preparedProject.workspacePurpose === 'world-engine'
        ? options.world?.communityOrigin
        : undefined,
      createdAt: now,
      updatedAt: now,
    }
    const worldId = await db.worlds.add(world) as number
    const work = buildWorkRecord({
      projectId,
      worldId,
      fallback: {
        genres,
        targetWordCount: input.targetWordCount,
        writingStyleId: input.writingStyleId,
        methodologyId: input.methodologyId,
        includeCultivationProgressInAI: input.includeCultivationProgressInAI ?? false,
      },
      create: {
        title: preparedProject.name,
        description: input.description,
        genres,
        customGenre: input.customGenre,
        status: input.status,
        targetWordCount: input.targetWordCount,
        coverImage: input.coverImage,
        activeCharacterDrivenPlanId: input.activeCharacterDrivenPlanId,
        kind: options.kind,
        novelProfile: options.novelProfile,
      },
      now,
    })
    const workId = await db.works.add(work) as number
    const scope = { projectId, worldId, workId }
    if (work.kind === 'novel' && work.novelProfile === 'short') {
      await createShortNovelSkeleton(scope, work.targetWordCount, options.preferredChapterCount, initialChapterSummary, initialChapterContent, now)
      await db.shortNovelProductions.add(buildShortNovelProductionRecordV1(scope, now))
    }
    if (importedNovelText) {
      const chunks = chunkDocument(importedNovelText, { targetChars: 20_000, overlapChars: 0 })
      for (let index = 0; index < chunks.length; index++) {
        // Use original offsets to retain paragraph separators and any preface exactly once.
        const content = importedNovelText.slice(index === 0 ? 0 : chunks[index].startChar, index + 1 < chunks.length ? chunks[index + 1].startChar : importedNovelText.length)
        const title = chunks[index].label || `原作第 ${index + 1} 部分`
        const outlineNodeId = await db.outlineNodes.add(stampNewRecord(scope, 'outlineNodes', { projectId, parentId: null, type: 'chapter', title, summary: '', order: index, createdAt: now, updatedAt: now }, { owner: 'work' })) as number
        await db.chapters.add(stampNewRecord(scope, 'chapters', { projectId, outlineNodeId, title, content: plainTextToHtml(content), wordCount: countWords(content), status: 'draft', order: index, notes: '', createdAt: now, updatedAt: now }, { owner: 'work' }))
      }
    }
    const createdWorld = { ...world, id: worldId }
    const createdWork = { ...work, id: workId }
    const projectPatch = { activeWorldId: worldId, activeWorkId: workId }
    await db.projects.update(projectId, { ...projectPatch, updatedAt: now })
    return {
      project: { ...preparedProject, ...projectPatch, id: projectId, updatedAt: now },
      world: createdWorld,
      work: createdWork,
      scope,
    }
  })
}

src/lib/workspace/lifecycle.ts.source:
/**
 * Workspace/World/Work 生命周期边界。
 *
 * World owns canon; Work owns authored projections. Deleting a Work must never
 * touch World-owned rows, while deleting a World requires explicit confirmation
 * before removing its Works and all dependent content.
 */
import { db } from '../db/schema'
import { PROJECT_TABLES, REGISTRY_BY_NAME } from '../registry/project-tables'
import { transactionTablesFor, cascadeDeleteProject } from '../registry/lifecycle'
import { resolveWorkspaceOwnership } from './ownership'
import { markAndSweepAgentRunArtifactsV1 } from '../memory/artifact-retention-store'
import { remapNarrativeDomainReferencesV1 } from '../narrative-domain/lifecycle'

function ownerField(spec: typeof PROJECT_TABLES[number]): { owner: 'world' | 'work'; field: string } | null {
  const locator = spec.domainOwner?.locator
  if (locator?.kind === 'field' && (locator.owner === 'world' || locator.owner === 'work')) {
    return { owner: locator.owner, field: locator.field }
  }
  return null
}

function parseSimpleTarget(target: string): { tableName: string; field: string } | null {
  const match = target.match(/^([^[]+)\[([^\]]+)\]$/)
  return match ? { tableName: match[1], field: match[2] } : null
}

async function rowsReferencingField(
  table: typeof PROJECT_TABLES[number]['table'],
  field: string,
  sourceId: number,
): Promise<any[]> {
  const dexieTable = table as any
  const indexed = dexieTable.schema?.primKey?.keyPath === field
    || dexieTable.schema?.idxByName?.[field] != null
  if (indexed) return dexieTable.where(field).equals(sourceId).toArray()
  // PROJECT_TABLES may govern semantically important but intentionally
  // unindexed optional references. Deletion is rare and correctness is more
  // important than forcing every nullable evidence pointer into the schema.
  return (await dexieTable.toArray()).filter((row: Record<string, unknown>) => row[field] === sourceId)
}

export async function cascadeRegisteredReferences(
  sourceTableName: string,
  sourceId: number,
  visited = new Set<string>(),
): Promise<void> {
  const visitKey = `${sourceTableName}:${sourceId}`
  if (visited.has(visitKey)) return
  visited.add(visitKey)
  const source = REGISTRY_BY_NAME.get(sourceTableName)
  if (!source) throw new Error(`[workspace-lifecycle] 未登记表 ${sourceTableName}`)
  await remapNarrativeDomainReferencesV1({ table: sourceTableName, fromId: sourceId })
  for (const ref of source.refs ?? []) {
    if (ref.kind !== 'simple' || ref.onDelete === 'keep') continue
    const target = parseSimpleTarget(ref.target)
    if (!target) throw new Error(`[workspace-lifecycle] 无效引用 ${sourceTableName} -> ${ref.target}`)
    const targetSpec = REGISTRY_BY_NAME.get(target.tableName)
    if (!targetSpec) throw new Error(`[workspace-lifecycle] 引用目标未登记 ${target.tableName}`)
    const rows = await rowsReferencingField(targetSpec.table, target.field, sourceId)
    for (const row of rows) {
      if (row.id == null) continue
      if (ref.onDelete === 'setNull') {
        await targetSpec.table.update(row.id, { [target.field]: null })
      } else {
        await cascadeRegisteredReferences(target.tableName, row.id, visited)
        await targetSpec.table.delete(row.id)
      }
    }
  }
}

async function deleteOwnerRows(owner: 'world' | 'work', ownerId: number): Promise<void> {
  for (const spec of PROJECT_TABLES) {
    if (!spec.table || spec.name === 'projects' || spec.name === 'worlds' || spec.name === 'works') continue
    const locator = spec.domainOwner?.locator
    if (locator?.kind === 'field' && locator.owner === owner) {
      const rows = (await spec.table.toArray()).filter(row => (row as any)[locator.field] === ownerId)
      for (const row of rows) {
        if (row.id == null) continue
        await cascadeRegisteredReferences(spec.name, row.id)
        await spec.table.delete(row.id)
      }
    } else if (locator?.kind === 'exclusive-fields') {
      const field = owner === 'world' ? locator.worldField : locator.workField
      const rows = (await spec.table.toArray()).filter(row => (row as any)[field] === ownerId)
      for (const row of rows) {
        if (row.id == null) continue
        await cascadeRegisteredReferences(spec.name, row.id)
        await spec.table.delete(row.id)
      }
    } else if (locator?.kind === 'exclusive-work-instance' && owner === 'work') {
      const rows = (await spec.table.toArray()).filter(row => (row as any)[locator.workField] === ownerId)
      for (const row of rows) {
        if (row.id == null) continue
        await cascadeRegisteredReferences(spec.name, row.id)
        await spec.table.delete(row.id)
      }
    }
  }
}

export async function deleteWork(workId: number): Promise<void> {
  const work = await db.works.get(workId)
  if (!work) return
  await resolveWorkspaceOwnership(work.projectId)
  await db.transaction('rw', transactionTablesFor('deleteProject'), async () => {
    await cascadeRegisteredReferences('works', workId)
    await deleteOwnerRows('work', workId)
    await db.works.delete(workId)
    const project = await db.projects.get(work.projectId)
    if (project?.activeWorkId === workId) {
      const replacement = await db.works.where('worldId').equals(work.worldId).sortBy('updatedAt')
      const nextWork = replacement[replacement.length - 1]
      const world = await db.worlds.get(work.worldId)
      if (!world) throw new Error('[workspace-lifecycle] Work 的语义作用域根在删除过程中丢失')
      await db.projects.update(work.projectId, {
        activeWorldId: world.id!,
        activeWorkId: nextWork?.id ?? null,
        updatedAt: Date.now(),
      })
    }
  })
  await markAndSweepAgentRunArtifactsV1(work.projectId)
}

export async function deleteWorld(worldId: number, options: { confirm: boolean } = { confirm: false }): Promise<void> {
  const world = await db.worlds.get(worldId)
  if (!world) return
  const works = await db.works.where('worldId').equals(worldId).toArray()
  if (works.length && !options.confirm) {
    throw new Error('[workspace-lifecycle] 删除 World 前必须显式确认其 Works 将一并删除')
  }
  await resolveWorkspaceOwnership(world.projectId)
  await db.transaction('rw', transactionTablesFor('deleteProject'), async () => {
    for (const work of works) {
      await cascadeRegisteredReferences('works', work.id!)
      await deleteOwnerRows('work', work.id!)
    }
    await db.works.bulkDelete(works.map(work => work.id!).filter(Boolean))
    await cascadeRegisteredReferences('worlds', worldId)
    await deleteOwnerRows('world', worldId)
    await db.worlds.delete(worldId)
    const project = await db.projects.get(world.projectId)
    if (project?.activeWorldId === worldId) {
      const replacement = await db.worlds.where('projectId').equals(world.projectId).sortBy('updatedAt')
      const nextWorld = replacement[replacement.length - 1]
      let nextWork
      if (nextWorld?.id != null) {
        const candidates = await db.works.where('worldId').equals(nextWorld.id).sortBy('updatedAt')
        nextWork = candidates[candidates.length - 1]
      }
      await db.projects.update(world.projectId, {
        activeWorldId: nextWorld?.id ?? null,
        activeWorkId: nextWork?.id ?? null,
        updatedAt: Date.now(),
      })
    }
  })
  await markAndSweepAgentRunArtifactsV1(world.projectId)
}

export async function deleteWorkspace(projectId: number): Promise<void> {
  await cascadeDeleteProject(projectId)
}

export function registeredOwnerField(tableName: string): { owner: 'world' | 'work'; field: string } | null {
  const spec = PROJECT_TABLES.find(candidate => candidate.name === tableName)
  return spec ? ownerField(spec) : null
}

src/lib/workspace/scope.ts.source:
/**
 * 统一 Workspace/World/Work 作用域门。
 *
 * 逻辑归属只从 PROJECT_TABLES.domainOwner 派生。这个模块不维护第二份表清单，
 * 也不允许调用方把 AI 返回的 owner id 当成可信输入。
 */
import { resolveWorkspaceScope } from './ownership'
import type { Table } from 'dexie'
import { db } from '../db/schema'
import { PROJECT_TABLES } from '../registry/project-tables'
import type { DomainOwnerKind, TableSpec } from '../registry/types'
import type { WorkspaceScope } from '../types/world-ownership'
import { stampResourceIdentityV1 } from '../context-gateway/resource-uid'

export type ScopeOwner = Exclude<DomainOwnerKind, 'instance'>

export interface ScopeInput {
  projectId?: number
  scope?: WorkspaceScope
}

export interface ScopeReadOptions {
  owner?: ScopeOwner
}

/** Public convenience input. A physical project id is always resolved to the
 * current World/Work roots before any data is read or written. */
export type WorkspaceScopeLike = number | WorkspaceScope

export function asScopeInput(value: WorkspaceScopeLike): ScopeInput {
  return typeof value === 'number' ? { projectId: value } : { scope: value }
}

export function scopeProjectId(value: WorkspaceScopeLike): number {
  return typeof value === 'number' ? value : value.projectId
}

export async function resolveScopeLike(value: WorkspaceScopeLike): Promise<WorkspaceScope> {
  return resolveScope(asScopeInput(value))
}

export async function resolveReadScopeLike(value: WorkspaceScopeLike): Promise<WorkspaceScope> {
  return resolveReadScope(asScopeInput(value))
}

const REGISTRY_BY_NAME = new Map(PROJECT_TABLES.map(spec => [spec.name, spec] as const))

function fail(message: string): never {
  throw new Error(`[scope] ${message}`)
}

export async function resolveScope(input: ScopeInput): Promise<WorkspaceScope> {
  if (input.scope) {
    const scope = input.scope
    if (
      !Number.isInteger(scope.projectId)
      || !Number.isInteger(scope.worldId)
      || !Number.isInteger(scope.workId)
      || scope.projectId <= 0
      || scope.worldId <= 0
      || scope.workId <= 0
    ) {
      fail('WorkspaceScope 必须包含有效的 projectId/worldId/workId')
    }
    if (input.projectId != null && input.projectId !== scope.projectId) {
      fail('projectId 与 WorkspaceScope.projectId 不一致')
    }
    const [project, world, work] = await Promise.all([
      db.projects.get(scope.projectId),
      db.worlds.get(scope.worldId),
      db.works.get(scope.workId),
    ])
    if (!project || world?.projectId !== scope.projectId || work?.projectId !== scope.projectId || work.worldId !== scope.worldId) {
      fail('WorkspaceScope 不是当前工作区的有效 World/Work')
    }
    return scope
  }
  if (input.projectId == null) fail('缺少 projectId 或 WorkspaceScope')
  return resolveWorkspaceScope(input.projectId)
}

/** Reads and writes share the same current scope contract; there is no
 * project-only or pre-cutover database path. */
export async function resolveReadScope(input: ScopeInput): Promise<WorkspaceScope> {
  return resolveScope(input)
}

/** Tables required when a caller invokes a scope-validating write inside its own transaction. */
export function scopeTransactionTables(...tables: Table[]): Table[] {
  return [...new Set([db.projects, db.worlds, db.works, ...tables])]
}

export function getTableSpec(tableName: string): TableSpec {
  const spec = REGISTRY_BY_NAME.get(tableName)
  if (!spec) fail(`目标表 ${tableName} 未登记在 PROJECT_TABLES`)
  return spec
}

function rowProjectId(row: Record<string, unknown>): number | undefined {
  return typeof row.projectId === 'number' ? row.projectId : undefined
}

function scopeValue(scope: WorkspaceScope, owner: ScopeOwner): number | undefined {
  if (owner === 'world') return scope.worldId
  if (owner === 'work') return scope.workId
  return scope.projectId
}

function locatorOwner(spec: TableSpec, requested?: ScopeOwner): ScopeOwner | null {
  const locator = spec.domainOwner?.locator
  if (!locator || locator.kind === 'workspace') return null
  if (locator.kind === 'field') {
    return locator.owner === 'instance' ? null : locator.owner
  }
  if (locator.kind === 'exclusive-fields') return requested ?? (spec.domainOwner?.defaultOwner as ScopeOwner)
  if (locator.kind === 'exclusive-work-instance') return 'work'
  if (locator.kind === 'parent') {
    if (locator.owner === 'inherit') return requested ?? (spec.domainOwner?.defaultOwner as ScopeOwner)
    return locator.owner === 'instance' ? null : locator.owner
  }
  return requested ?? null
}

function directOwnerMatches(spec: TableSpec, row: Record<string, unknown>, scope: WorkspaceScope, requested?: ScopeOwner): boolean {
  // The LocalWorkspace root is the only project-owned row whose physical key
  // is the project identity instead of a projectId column.
  if (spec.name === 'projects') return row.id === scope.projectId
  const physicalProjectId = rowProjectId(row)
  if (
    spec.owner !== 'global'
    && (
      (spec.owner === 'project' || spec.owner === 'transient')
        ? physicalProjectId !== scope.projectId
        : physicalProjectId != null && physicalProjectId !== scope.projectId
    )
  ) return false
  const domain = spec.domainOwner
  if (!domain) return spec.owner === 'global' || rowProjectId(row) === scope.projectId
  const locator = domain.locator
  if (locator.kind === 'workspace') return rowProjectId(row) === scope.projectId
  if (locator.kind === 'field') {
    if (locator.owner === 'instance') return false
    return row[locator.field] === scopeValue(scope, locator.owner)
  }
  if (locator.kind === 'exclusive-fields') {
    const hasWorld = row[locator.worldField] != null
    const hasWork = row[locator.workField] != null
    if (hasWorld === hasWork) return false
    const owner = requested ?? (hasWorld ? 'world' : 'work')
    return owner === 'world'
      ? hasWorld && row[locator.worldField] === scope.worldId
      : hasWork && row[locator.workField] === scope.workId
  }
  if (locator.kind === 'exclusive-work-instance') {
    const hasWork = row[locator.workField] != null
    const hasInstance = row[locator.instanceField] != null
    return hasWork !== hasInstance
      && hasWork
      && row[locator.workField] === scope.workId
      && (requested == null || requested === 'work')
  }
  // Parent locators are validated by assertRecordInScope, after loading the parent.
  return rowProjectId(row) === scope.projectId
}

/**
 * Check one row without trusting any id supplied by a prompt or component.
 * Parent-owned records inherit their scope from the registered parent row.
 */
export async function assertRecordInScope(
  scope: WorkspaceScope,
  tableName: string,
  row: unknown,
  options: ScopeReadOptions = {},
): Promise<boolean> {
  if (!row || typeof row !== 'object') return false
  const record = row as Record<string, unknown>
  const spec = getTableSpec(tableName)
  if (spec.owner === 'global') return true
  const locator = spec.domainOwner?.locator
  if (locator?.kind === 'parent') {
    const parentSpec = getTableSpec(locator.table)
    const parentId = record[locator.field]
    if (parentId == null) return false
    const parent = await parentSpec.table.get(parentId as number)
    return !!parent && await assertRecordInScope(scope, parentSpec.name, parent, { owner: options.owner })
  }
  return directOwnerMatches(spec, record, scope, options.owner)
}

/** Read only rows owned by the supplied scope. No component should hand-roll this filter. */
export async function readOwnedRows<T = Record<string, unknown>>(
  scope: WorkspaceScope,
  tableName: string,
  options: ScopeReadOptions = {},
): Promise<T[]> {
  const spec = getTableSpec(tableName)
  if (spec.owner === 'global') return spec.table.toArray() as Promise<T[]>
  // The current schema keeps projectId on physical rows. Filtering in memory here is
  // intentional until each domain table receives a dedicated owner index; correctness
  // takes precedence over an unsafe project-wide query.
  const rows = spec.owner === 'project' || spec.owner === 'transient'
    ? await spec.table.where('projectId').equals(scope.projectId).toArray()
    : await spec.table.toArray()
  // Keep this to one awaited Promise while callers may be inside a Dexie
  // transaction. Most direct-owner checks resolve without issuing another IDB
  // request; awaiting them one by one can let a browser auto-commit a large
  // transaction before the caller performs its write.
  const records = rows as Record<string, unknown>[]
  const ownership = await Promise.all(records.map(row => (
    assertRecordInScope(scope, tableName, row, options)
  )))
  return records.filter((_, index) => ownership[index]) as T[]
}

/** Stamp a new row from trusted scope. Existing owner ids must agree or the write fails closed. */
export function stampNewRecord<T>(
  scope: WorkspaceScope,
  tableName: string,
  input: T,
  options: ScopeReadOptions = {},
): T {
  const spec = getTableSpec(tableName)
  const result: Record<string, unknown> = { ...(input as Record<string, unknown>), projectId: scope.projectId }
  stampResourceIdentityV1(spec, result)
  const owner = locatorOwner(spec, options.owner)
  const locator = spec.domainOwner?.locator
  if (!locator || locator.kind === 'workspace' || owner == null) {
    if (result.worldId != null || result.workId != null) fail(`${tableName} 不允许携带 World/Work owner`)
    return result as T
  }
  if (locator.kind === 'exclusive-fields') {
    const selected = owner === 'world' ? 'worldId' : 'workId'
    const other = selected === 'worldId' ? 'workId' : 'worldId'
    if (result[selected] != null && result[selected] !== scopeValue(scope, owner)) fail(`${tableName}.${selected} 越过当前 scope`)
    if (result[other] != null) fail(`${tableName} 不能同时绑定 World 和 Work`)
    result[selected] = scopeValue(scope, owner)
    result[other] = null
  } else if (locator.kind === 'exclusive-work-instance') {
    if (owner !== 'work') fail(`${tableName} 通用 scope 只能创建 Work-owned 记录`)
    if (result[locator.workField] != null && result[locator.workField] !== scope.workId) {
      fail(`${tableName}.${locator.workField} 越过当前 scope`)
    }
    if (result[locator.instanceField] != null) fail(`${tableName} 不能同时绑定 Work 和运行实例`)
    result[locator.workField] = scope.workId
    result[locator.instanceField] = null
  } else if (locator.kind === 'field') {
    const field = locator.field
    const expected = scopeValue(scope, owner)
    if (result[field] != null && result[field] !== expected) fail(`${tableName}.${field} 越过当前 scope`)
    result[field] = expected
  }
  return result as T
}

export function assertScopedForeignKey(
  scope: WorkspaceScope,
  tableName: string,
  row: unknown,
  options?: ScopeReadOptions,
): Promise<boolean> {
  return assertRecordInScope(scope, tableName, row, options)
}

